Translate("frFR", "medivh", {
	title = "Medivh",
	subtitle = "Le dernier Gardien de Tirisfal",
	allegiance = "Ordre de Tirisfal · Karazhan",
	sections = {
		{
			title = "Résumé",
			text = [=[Medivh fut le dernier Gardien de {link:tirisfal-glades}Tirisfal{/link}, le champion secret que les mages les plus sages du monde dotèrent de pouvoirs pour tenir tête à la {link:burning-legion}Légion ardente{/link}. Il était le fils de la Gardienne {link:aegwynn}Aegwynn{/link} et de Nielas Aran, conjurateur de la cour de {link:stormwind-city}Stormwind{/link}. Il était aussi le plus cher ami du roi {link:llane-wrynn}Llane Wrynn{/link} et de sire {link:anduin-lothar}Anduin Lothar{/link}. Pourtant, la puissance qui aurait dû protéger {link:azeroth}Azeroth{/link} fut empoisonnée avant même son premier souffle, et c'est Medivh qui ouvrit aux orcs le chemin de ce monde.]=],
		},
		{
			title = "Importance",
			text = [=[Aucun mortel n'a fait davantage pour ouvrir l'âge des guerres. Par Medivh, le seigneur démon {link:sargeras}Sargeras{/link} tendit la main vers le monde et lança la {link:horde}Horde{/link} contre les royaumes {link:humans}humains{/link}. La {link:first-war}Première Guerre{/link}, la chute de {link:stormwind-city}Stormwind{/link} et toutes les guerres qui suivirent prennent racine dans la tour où il vivait.]=],
		},
		{
			title = "Une naissance empoisonnée",
			text = [=[{link:aegwynn}Aegwynn{/link} voulait que son fils soit son héritier, libre du conseil qui avait tenté de la gouverner. Elle ignorait que {link:sargeras}Sargeras{/link} avait caché son esprit en elle depuis le jour où elle avait abattu son avatar. Quand Medivh fut conçu, le seigneur démon passa dans l'enfant à naître. Le garçon grandit vif et doux, et il parcourait les bois du royaume avec {link:llane-wrynn}Llane{/link} et {link:anduin-lothar}Lothar{/link}. À quatorze ans, la puissance du Gardien s'éveilla en lui, et avec elle les ténèbres qui se cachaient dessous. Medivh sombra dans un sommeil qu'aucun guérisseur ne put briser. Pendant des années, il resta aux soins des clercs de l'{link:northshire-abbey}abbaye de Northshire{/link}. Quand il s'éveilla, c'était un homme fait, et il ne dit rien de ce qu'il avait vu dans les ténèbres.]=],
		},
		{
			title = "Karazhan",
			text = [=[Medivh s'installa à {link:karazhan}Karazhan{/link}, une tour isolée dans la contrée que l'on nomme aujourd'hui {link:deadwind-pass}Défilé de Deuillevent{/link}. Là, guidé par la volonté qui vivait en lui, il tendit la main à travers le vide vers un monde mourant appelé {red:draenor}Draenor{/red}. Il y trouva le démoniste {link:orcs}orc{/link} {link:gul-dan}Gul'dan{/link}, et ensemble ils ouvrirent la {link:dark-portal}Porte des Ténèbres{/link}. Le {link:kirin-tor}Kirin Tor{/link} de {link:dalaran}Dalaran{/link} lui envoya un jeune apprenti, {link:khadgar}Khadgar{/link}, qui en vint à redouter ce qu'il voyait dans la tour. La demi-orque {link:garona}Garona{/link} vint aussi à Karazhan comme émissaire de la {link:horde}Horde{/link}. Par Khadgar et Garona, la vérité parvint enfin à {link:stormwind-city}Stormwind{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Dans sa jeunesse, il leva sa puissance contre les trolls du sud, aux côtés de {link:llane-wrynn}Llane{/link} et de {link:anduin-lothar}Lothar{/link}.
• Il ouvrit la {link:dark-portal}Porte des Ténèbres{/link} avec {link:gul-dan}Gul'dan{/link} et les démonistes de Draenor.
• Il prit {link:khadgar}Khadgar{/link} comme apprenti et le laissa apprendre plus qu'il ne voulait en révéler.
• Il regarda depuis sa tour la {link:horde}Horde{/link} incendier le royaume de ses plus vieux amis.]=],
		},
		{
			title = "Destin",
			text = [=[{link:anduin-lothar}Anduin Lothar{/link} et {link:khadgar}Khadgar{/link} gravirent {link:karazhan}Karazhan{/link} pour mettre fin à la guerre à sa racine. Avec l'aide de {link:garona}Garona{/link}, ils affrontèrent le Gardien, et c'est là que Medivh fut tué. À l'instant de sa mort, {link:gul-dan}Gul'dan{/link} tenta d'arracher les secrets de la tombe de {link:sargeras}Sargeras{/link} à son esprit mourant, et y gagna pour sa peine une longue torpeur. Medivh est mort. Sa tour se dresse vide et silencieuse au-dessus du {link:deadwind-pass}Défilé de Deuillevent{/link}, et les gens du {link:duskwood}Bois de la Pénombre{/link} disent que d'étranges lueurs brillent encore à ses fenêtres.]=],
		},
		{
			title = "Non consigné",
			text = [=[Ce que Medivh savait, ce qu'il choisit et ce que {link:sargeras}Sargeras{/link} choisit pour lui ne peuvent plus être démêlés. Les chroniques laissent cette question ouverte.]=],
		},
	},
	bonds = {
		{ id = "aegwynn", name = "Aegwynn", note = "sa mère" },
		{ id = "llane-wrynn", name = "Llane Wrynn", note = "son ami d'enfance" },
		{ id = "anduin-lothar", name = "Anduin Lothar", note = "son ami, et son meurtrier" },
		{ id = "gul-dan", name = "Gul'dan", note = "ouvrit la Porte des Ténèbres avec lui" },
		{ id = "khadgar", name = "Khadgar", note = "son apprenti" },
	},
})

Translate("frFR", "aegwynn", {
	title = "Aegwynn",
	subtitle = "Gardienne de Tirisfal",
	allegiance = "Ordre de Tirisfal",
	sections = {
		{
			title = "Résumé",
			text = [=[Aegwynn fut Gardienne de {link:tirisfal-glades}Tirisfal{/link} plus longtemps que la plupart des royaumes n'ont duré. Le conseil secret de Tirisfal, formé des plus grands mages des terres {link:humans}humaines{/link} et {link:high-elves}elfiques{/link}, la choisit comme championne contre la {link:burning-legion}Légion ardente{/link} et lui donna la puissance et une vie de plusieurs siècles. On se souvient d'elle comme de la plus puissante de tous les Gardiens, et comme de celle qui fit le plus de mal sans jamais le vouloir.]=],
		},
		{
			title = "Importance",
			text = [=[En une seule victoire, Aegwynn porta à la Légion le coup le plus dur qu'elle ait jamais subi sur {link:azeroth}Azeroth{/link}. Au même instant, elle ouvrit la porte à son plus grand triomphe. Le seigneur démon {link:sargeras}Sargeras{/link} se cacha en elle, et par elle il passa dans son fils, {link:medivh}Medivh{/link}.]=],
		},
		{
			title = "La Gardienne",
			text = [=[Aegwynn était fière et intrépide, et elle refusait d'être la marionnette du conseil. Elle traquait les démons partout où ils marchaient, et elle porta le manteau pendant de nombreuses vies d'hommes. En {red:northrend}Norfendre{/red}, elle trouva des démons qui chassaient les derniers dragons du nord et drainaient leur magie. Avec l'aide des dragons, elle les détruisit. Alors {link:sargeras}Sargeras{/link} lui-même apparut devant elle dans une grande tempête. Aegwynn combattit son avatar et le tua. Elle scella son corps brisé dans une antique salle engloutie sous la mer lors de la {link:great-sundering}Grande Fracture{/link}, afin qu'il ne puisse jamais se relever. Elle crut le maître de la Légion vaincu. Elle ignorait que son esprit s'était glissé dans le sien.]=],
		},
		{
			title = "L'héritier de la Gardienne",
			text = [=[Au fil des longues années qui suivirent, Aegwynn s'éloigna du conseil. Elle en vint à croire que ses membres se mêlaient des affaires des rois, et elle résolut qu'ils ne choisiraient jamais le prochain Gardien. Elle prit pour compagnon Nielas Aran, conjurateur de la cour de {link:stormwind-city}Stormwind{/link}, et lui donna un fils. Elle plaça la puissance de {link:tirisfal-glades}Tirisfal{/link} dans l'enfant, pour qu'elle s'éveille à sa majorité. Puis elle laissa le garçon à son père et se retira du monde.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle porta le manteau de Gardienne pendant de nombreux siècles et détruisit des démons dans tous les {link:eastern-kingdoms}Royaumes de l'est{/link}.
• Elle défendit les dragons de Norfendre contre les chasseurs de la Légion.
• Elle tua l'avatar de {link:sargeras}Sargeras{/link} et ensevelit son corps sous la mer.
• Elle défia le conseil de {link:tirisfal-glades}Tirisfal{/link} et choisit son propre héritier.]=],
		},
		{
			title = "Destin",
			text = [=[Aegwynn survécut au fils qu'elle avait conçu. Quand la {link:dark-portal}Porte des Ténèbres{/link} s'ouvrit et que la {link:horde}Horde{/link} arriva, le monde apprit ce que son orgueil avait coûté. {link:medivh}Medivh{/link} tomba à {link:karazhan}Karazhan{/link}, et la lignée des Gardiens s'éteignit avec lui. Aegwynn elle-même partit en exil, sa puissance épuisée. On murmure parmi les érudits de {link:theramore-isle}Theramore{/link} qu'une vieille femme d'une grande sagesse a vécu un temps dans les terres sauvages de {link:kalimdor}Kalimdor{/link} et a conseillé dame {link:jaina-proudmoore}Jaina Proudmoore{/link}. Peu connaissent son nom, et ceux qui le connaissent le gardent pour eux.]=],
		},
		{
			title = "Non consigné",
			text = [=[Les histoires ne disent pas comment Aegwynn fut choisie la première fois, ni combien d'années elle porta le manteau en tout. Cette entrée ne consigne que ce qui est certain.]=],
		},
	},
	bonds = {
		{ id = "medivh", name = "Medivh", note = "son fils" },
		{ id = "jaina-proudmoore", name = "Jaina Proudmoore", note = "qu'elle aurait conseillée" },
	},
})

Translate("frFR", "llane-wrynn", {
	title = "Llane Wrynn",
	subtitle = "Roi de Stormwind pendant la Première Guerre",
	allegiance = "Royaume de Stormwind · Maison Wrynn",
	aliases = { "Llane", "roi Llane" },
	sections = {
		{
			title = "Résumé",
			text = [=[Llane Wrynn était roi de {link:stormwind-city}Stormwind{/link} quand la {link:horde}Horde{/link} franchit la {link:dark-portal}Porte des Ténèbres{/link}. C'était un souverain fier et courageux, l'ami d'enfance de {link:medivh}Medivh{/link} et d'{link:anduin-lothar}Anduin Lothar{/link}, et le père du roi {link:varian-wrynn}Varian Wrynn{/link}. Il mena son peuple à travers la longue agonie de la {link:first-war}Première Guerre{/link} et mourut dans son propre donjon tandis que sa cité tombait.]=],
		},
		{
			title = "Importance",
			text = [=[Llane fut le dernier roi de l'ancienne {link:stormwind-city}Stormwind{/link}. Sa mort marqua la fin d'un royaume resté seul et fier pendant des générations. De sa ruine naquit l'{link:alliance}Alliance{/link}, car les survivants qu'il laissa derrière lui portèrent l'avertissement des orcs vers le nord, jusqu'en {link:lordaeron}Lordaeron{/link}.]=],
		},
		{
			title = "Jeunesse",
			text = [=[Llane grandit en compagnie de deux garçons remarquables : {link:anduin-lothar}Anduin Lothar{/link}, héritier d'une lignée antique, et {link:medivh}Medivh{/link}, fils du conjurateur de la cour. Les trois étaient inséparables. Quand Medivh sombra dans son long sommeil, Llane devint un homme sans lui, et il se réjouit quand son ami s'éveilla. Cette amitié allait l'aveugler dans les années à venir.]=],
		},
		{
			title = "La Première Guerre",
			text = [=[Quand d'étranges créatures furent aperçues dans le Noir Marécage, Llane envoya {link:anduin-lothar}Lothar{/link} découvrir ce qu'elles étaient. C'étaient des orcs, et ce n'étaient que les premiers. Llane nomma Lothar son champion et envoya des messagers aux autres royaumes humains, mais peu crurent à ce récit. Pendant des années, {link:stormwind-city}Stormwind{/link} combattit seule. Des villages brûlèrent dans la {link:elwynn-forest}forêt d'Elwynn{/link}, en {link:westfall}Marche de l'Ouest{/link} et dans {link:redridge-mountains}les Carmines{/link}. La {link:horde}Horde{/link} assiégea la capitale et fut repoussée, car Lothar frappa ses arrières par surprise. Quand {link:khadgar}Khadgar{/link} et la demi-orque {link:garona}Garona{/link} avertirent le roi que {link:medivh}Medivh{/link} lui-même avait amené les envahisseurs, Llane refusa de croire que son ami puisse le trahir.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il nomma {link:anduin-lothar}Anduin Lothar{/link} champion du royaume et lui confia sa défense.
• Il envoya des avertissements sur les orcs aux autres royaumes humains.
• Il tint {link:stormwind-city}Stormwind{/link} contre le premier grand siège de la {link:horde}Horde{/link}.
• Il fit de {link:garona}Garona{/link} sa confidente après la chute de {link:medivh}Medivh{/link}.]=],
		},
		{
			title = "Destin",
			text = [=[Après la mort de {link:medivh}Medivh{/link}, l'{link:orcs}orc{/link} {link:orgrim-doomhammer}Orgrim Doomhammer{/link} prit le commandement de la {link:horde}Horde{/link} et la mena de nouveau contre {link:stormwind-city}Stormwind{/link}. Les murs furent percés, mais Llane tint le donjon. {link:garona}Garona{/link}, devenue sa conseillère de confiance, restait liée à la volonté des démonistes de la Horde. Elle tua le roi dans sa chambre. Le jeune prince {link:varian-wrynn}Varian{/link} vit mourir son père. Stormwind tomba, et la Horde la rasa. {link:anduin-lothar}Lothar{/link} rassembla les survivants et les mena de l'autre côté de la mer, jusqu'en {link:lordaeron}Lordaeron{/link}. Le royaume de Llane a depuis été rebâti, et son fils a régné sur son trône jusqu'à sa récente disparition. Son petit-fils, {link:anduin-wrynn}Anduin Wrynn{/link}, attend aujourd'hui dans le donjon rebâti, nommé d'après le champion qui sauva sa famille.]=],
		},
		{
			title = "Non consigné",
			text = [=[Les chroniques disent peu de chose de la reine de Llane ou des années de son règne avant l'ouverture de la Porte.]=],
		},
	},
	bonds = {
		{ id = "medivh", name = "Medivh", note = "son ami d'enfance" },
		{ id = "anduin-lothar", name = "Anduin Lothar", note = "son champion" },
		{ id = "varian-wrynn", name = "Varian Wrynn", note = "son fils" },
		{ id = "orgrim-doomhammer", name = "Orgrim Doomhammer", note = "mena la Horde qui prit sa cité" },
		{ id = "garona", name = "Garona", note = "sa conseillère, et sa meurtrière" },
	},
})

Translate("frFR", "anduin-lothar", {
	title = "Anduin Lothar",
	subtitle = "Le Lion d'Azeroth",
	allegiance = "Royaume de Stormwind · Alliance de Lordaeron",
	aliases = { "Lothar", "sire Anduin Lothar" },
	sections = {
		{
			title = "Résumé",
			text = [=[Sire Anduin Lothar fut le champion de {link:stormwind-city}Stormwind{/link} pendant la {link:first-war}Première Guerre{/link} et le premier commandant suprême de l'{link:alliance}Alliance{/link} pendant la {link:second-war}Deuxième Guerre{/link}. Il était le dernier héritier connu du sang royal d'{link:arathor}Arathor{/link}, l'empire antique dont sont issus les royaumes humains. Les soldats l'appelaient le Lion d'{link:azeroth}Azeroth{/link}. Sans lui, les nations {link:humans}humaines{/link} ne se seraient peut-être jamais unies.]=],
		},
		{
			title = "Importance",
			text = [=[Lothar sauva {link:stormwind-city}Stormwind{/link} deux fois : une fois en menant son peuple hors des cendres, et une fois en persuadant les rois du nord de se battre pour elle. L'{link:alliance}Alliance{/link} qu'il forgea perdure encore, et le petit-fils de son roi porte son nom.]=],
		},
		{
			title = "La Première Guerre",
			text = [=[Lothar était l'ami d'enfance de {link:llane-wrynn}Llane Wrynn{/link} et de {link:medivh}Medivh{/link}. Quand des orcs furent aperçus pour la première fois dans le Noir Marécage, le roi l'envoya en reconnaissance, et il revint avec l'annonce d'une guerre. Llane fit de lui le champion du royaume. Lothar combattit à travers le royaume pendant des années. Quand la {link:horde}Horde{/link} assiégea {link:stormwind-city}Stormwind{/link} pour la première fois, il mena les chevaliers du royaume par la mer pour la contourner et frappa ses arrières, brisant l'assaut. Avec le jeune mage {link:khadgar}Khadgar{/link}, il gravit {link:karazhan}Karazhan{/link} et affronta Medivh, son plus vieil ami, et c'est là que le Gardien fut tué. Pourtant, le royaume ne put être sauvé. Quand Stormwind tomba, Lothar mena les survivants vers le nord, de l'autre côté de la mer.]=],
		},
		{
			title = "La Deuxième Guerre",
			text = [=[En {link:lordaeron}Lordaeron{/link}, Lothar se présenta devant le roi {link:terenas-menethil}Terenas Menethil{/link} et les seigneurs des nations du nord, et les avertit que la {link:horde}Horde{/link} viendrait ensuite pour eux. Ils l'écoutèrent. L'{link:alliance}Alliance de Lordaeron{/link} naquit, et Lothar fut nommé son commandant. Les hauts-elfes de {link:quel-thalas}Quel'Thalas{/link} la rejoignirent, car ils avaient une dette antique envers le sang d'{link:arathor}Arathor{/link}, et Lothar en était le dernier héritier. Avec {link:khadgar}Khadgar{/link} et le jeune paladin {link:turalyon}Turalyon{/link} pour lieutenants, il combattit la Horde à travers les royaumes du nord et la repoussa vers le sud.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il repéra les premiers orcs dans le Noir Marécage et avertit son roi.
• Il brisa le premier siège de {link:stormwind-city}Stormwind{/link} par une charge venue de la mer.
• Il tua {link:medivh}Medivh{/link} à {link:karazhan}Karazhan{/link}, avec {link:khadgar}Khadgar{/link} à ses côtés.
• Il mena le peuple de Stormwind en exil en {link:lordaeron}Lordaeron{/link}.
• Il persuada les royaumes humains de s'unir, et il commanda leurs armées.]=],
		},
		{
			title = "Destin",
			text = [=[À la fin de la {link:second-war}Deuxième Guerre{/link}, Lothar poursuivit la {link:horde}Horde{/link} jusqu'au {link:blackrock-mountain}Mont Blackrock{/link}, dans les {link:burning-steppes}Steppes ardentes{/link}. Là, dans la bataille au pied de la montagne, il tomba sous les coups d'{link:orgrim-doomhammer}Orgrim Doomhammer{/link}. Sa mort ne brisa pas l'{link:alliance}Alliance{/link}. {link:turalyon}Turalyon{/link} reprit son épée, rallia les soldats endeuillés et écrasa la Horde. {link:stormwind-city}Stormwind{/link} fut reconquise, et le roi {link:varian-wrynn}Varian Wrynn{/link} nomma plus tard son fils Anduin en l'honneur du champion.]=],
		},
	},
	bonds = {
		{ id = "llane-wrynn", name = "Llane Wrynn", note = "son roi et ami" },
		{ id = "medivh", name = "Medivh", note = "son ami, et son ennemi" },
		{ id = "terenas-menethil", name = "Terenas Menethil", note = "lui confia le commandement de l'Alliance" },
		{ id = "orgrim-doomhammer", name = "Orgrim Doomhammer", note = "son meurtrier" },
		{ id = "turalyon", name = "Turalyon", note = "son lieutenant et successeur" },
		{ id = "anduin-wrynn", name = "Anduin Wrynn", note = "nommé en son honneur" },
	},
})

Translate("frFR", "tiffin-wrynn", {
	title = "Tiffin Wrynn",
	subtitle = "Reine de Stormwind",
	allegiance = "Royaume de Stormwind · Maison Wrynn",
	aliases = { "Tiffin", "reine Tiffin" },
	sections = {
		{
			title = "Résumé",
			text = [=[Tiffin Wrynn était la reine du roi {link:varian-wrynn}Varian Wrynn{/link} et la mère du prince {link:anduin-wrynn}Anduin Wrynn{/link}. Elle siégea aux côtés de Varian dans les années qui suivirent la {link:second-war}Deuxième Guerre{/link}, quand {link:stormwind-city}Stormwind{/link} se relevait de ses cendres. Elle ne vécut pas assez pour voir la cité achevée. Elle mourut dans l'émeute des tailleurs de pierre, victime de la querelle entre les nobles de la couronne et les hommes qui avaient rebâti leurs murs.]=],
		},
		{
			title = "Importance",
			text = [=[La mort de Tiffin est l'une des blessures silencieuses de la nouvelle {link:stormwind-city}Stormwind{/link}. Elle priva l'héritier du royaume d'une mère et son roi d'une épouse. Elle marqua aussi le moment où la colère des maçons se changea en révolte ouverte, d'où naquit la {link:defias-brotherhood}Confrérie défias{/link}.]=],
		},
		{
			title = "La reconstruction",
			text = [=[Après la {link:second-war}Deuxième Guerre{/link}, les exilés de {link:stormwind-city}Stormwind{/link} rentrèrent chez eux et trouvèrent leur cité en ruine. La {link:stonemasons-guild}guilde des Tailleurs de pierre{/link}, menée par {link:edwin-vancleef}Edwin VanCleef{/link}, travailla des années pour la relever. {link:varian-wrynn}Varian{/link}, le fils de {link:llane-wrynn}Llane Wrynn{/link}, monta sur le trône de ses pères. Tiffin devint sa reine, et avec le temps elle lui donna un fils, Anduin, nommé d'après le champion {link:anduin-lothar}Anduin Lothar{/link}. Un temps, il sembla que le royaume pourrait de nouveau connaître la paix.]=],
		},
		{
			title = "L'émeute",
			text = [=[La {link:house-of-nobles}Chambre des nobles{/link} avait promis de payer les maçons pour leur labeur. Une fois l'ouvrage terminé, les nobles refusèrent. Les maçons protestèrent dans les rues de la capitale, et la protestation tourna à l'émeute. Dans le chaos, la reine fut frappée et tuée. Les maçons furent chassés de la cité dans la disgrâce, et les plus amers d'entre eux s'enfuirent en {link:westfall}Marche de l'Ouest{/link}. Là, ils prirent le bandana rouge, et leur confrérie s'attaque au royaume depuis lors.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle fut reine de {link:stormwind-city}Stormwind{/link} dans les années qui suivirent sa reconstruction.
• Elle donna à {link:varian-wrynn}Varian{/link} un fils et héritier, Anduin.]=],
		},
		{
			title = "Destin",
			text = [=[Tiffin n'est plus. Son fils n'est encore qu'un enfant, et en ces jours il attend dans le donjon de {link:stormwind-city}Stormwind{/link} tandis que le sort de son père reste inconnu et que le généralissime {link:bolvar-fordragon}Bolvar Fordragon{/link} gouverne comme régent. Les maçons qui servaient jadis la couronne mènent désormais leur propre guerre contre elle depuis les mines et les fermes de la {link:westfall}Marche de l'Ouest{/link}. Beaucoup à Stormwind parlent encore de la reine avec amour, et de sa mort avec honte.]=],
		},
		{
			title = "Non consigné",
			text = [=[On a peu écrit sur la vie de Tiffin avant qu'elle ne devienne reine. Les chroniques consignent son mariage, son fils et sa mort, et presque rien de ses propres paroles ou de ses actes. Cette entrée ne comble pas ce silence par des suppositions.]=],
		},
	},
	bonds = {
		{ id = "varian-wrynn", name = "Varian Wrynn", note = "son époux" },
		{ id = "anduin-wrynn", name = "Anduin Wrynn", note = "son fils" },
		{ id = "llane-wrynn", name = "Llane Wrynn", note = "le père de son époux" },
		{ id = "edwin-vancleef", name = "Edwin VanCleef", note = "mena les maçons dont l'émeute lui coûta la vie" },
	},
})

Translate("frFR", "terenas-menethil", {
	title = "Terenas Menethil",
	subtitle = "Roi de Lordaeron",
	allegiance = "Royaume de Lordaeron · Alliance de Lordaeron",
	aliases = { "Terenas", "roi Terenas" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le roi Terenas Menethil II régnait sur {link:lordaeron}Lordaeron{/link}, le plus grand des royaumes {link:humans}humains{/link} du nord. C'est dans sa capitale que l'{link:alliance}Alliance{/link} fut fondée, et sous sa bannière que la {link:horde}Horde{/link} fut vaincue lors de la {link:second-war}Deuxième Guerre{/link}. Il était le père du prince {link:arthas-menethil}Arthas Menethil{/link} et de la princesse Calia. Il mourut de la main de son fils, et son royaume mourut avec lui.]=],
		},
		{
			title = "Importance",
			text = [=[Terenas fut la clé de voûte de l'{link:alliance}Alliance de Lordaeron{/link}. Il accueillit les réfugiés de {link:stormwind-city}Stormwind{/link} et écouta {link:anduin-lothar}Anduin Lothar{/link} quand d'autres rois s'y refusaient. Pourtant, la paix qui suivit sa victoire s'effilocha sous son règne, et le sort final de son royaume est le plus sombre de l'histoire de l'humanité.]=],
		},
		{
			title = "L'Alliance",
			text = [=[Quand {link:anduin-lothar}Lothar{/link} amena les exilés de {link:stormwind-city}Stormwind{/link} vers le nord, Terenas convoqua les seigneurs des nations humaines dans sa capitale. {link:gilneas}Gilneas{/link}, {link:kul-tiras}Kul Tiras{/link}, {link:stromgarde-keep}Stromgarde{/link}, l'{link:alterac-mountains}Alterac{/link} et {link:dalaran}Dalaran{/link} envoyèrent leurs souverains et leurs émissaires, et les hauts-elfes de {link:quel-thalas}Quel'Thalas{/link} les rejoignirent plus tard. Terenas confia à Lothar le commandement des armées réunies. Les terres de {link:lordaeron}Lordaeron{/link} souffrirent beaucoup de la guerre, mais à la fin la {link:horde}Horde{/link} fut brisée, et ses orcs furent faits prisonniers.]=],
		},
		{
			title = "Une paix qui s'effiloche",
			text = [=[Après la guerre, Terenas ordonna que les orcs capturés soient détenus dans de grands camps d'internement. Les camps coûtaient cher, et il imposa les autres nations pour les financer. Des querelles naquirent au sujet des camps et du sort du royaume traître d'{link:alterac-mountains}Alterac{/link}. L'un après l'autre, {link:gilneas}Gilneas{/link}, {link:stromgarde-keep}Stromgarde{/link} et {link:quel-thalas}Quel'Thalas{/link} quittèrent l'{link:alliance}Alliance{/link}. Quand une étrange peste se mit à se répandre dans les terres agricoles du nord de {link:lordaeron}Lordaeron{/link}, le roi envoya son fils {link:arthas-menethil}Arthas{/link} et le paladin {link:uther-the-lightbringer}Uther le Porteur de Lumière{/link} y mettre fin.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il accueillit les réfugiés de {link:stormwind-city}Stormwind{/link} dans son royaume.
• Il fonda l'{link:alliance}Alliance de Lordaeron{/link} et en confia le commandement à {link:anduin-lothar}Anduin Lothar{/link}.
• Il ordonna la construction des camps d'internement après la {link:second-war}Deuxième Guerre{/link}.
• Il envoya {link:arthas-menethil}Arthas{/link} et {link:uther-the-lightbringer}Uther{/link} contre la peste dans le nord.]=],
		},
		{
			title = "Destin",
			text = [=[{link:arthas-menethil}Arthas{/link} revint de {red:northrend}Norfendre{/red} en héros, et le peuple de la capitale sema des pétales de fleurs sur son passage. Le prince entra dans la salle du trône, s'agenouilla devant son père, puis le tua avec la lame runique {red:frostmourne}Deuillegivre{/red}. Avec la mort du roi, le royaume tomba aux mains du {link:scourge}Fléau{/link}. {link:uther-the-lightbringer}Uther{/link} porta plus tard les cendres du roi dans une urne en direction de {link:quel-thalas}Quel'Thalas{/link}, mais Arthas abattit le paladin et dispersa les cendres. La capitale de Terenas est en ruine, et sous elle les {link:forsaken}Réprouvés{/link} de dame {link:sylvanas-windrunner}Sylvanas Windrunner{/link} ont bâti l'{link:undercity}Undercity{/link}.]=],
		},
	},
	bonds = {
		{ id = "arthas-menethil", name = "Arthas Menethil", note = "son fils, et son meurtrier" },
		{ id = "anduin-lothar", name = "Anduin Lothar", note = "commandant de son Alliance" },
		{ id = "uther-the-lightbringer", name = "Uther le Porteur de Lumière", note = "son paladin loyal" },
		{ id = "alonsus-faol", name = "Alonsus Faol", note = "archevêque de sa foi" },
	},
})

Translate("frFR", "arthas-menethil", {
	title = "Arthas Menethil",
	subtitle = "Le prince déchu",
	allegiance = [=[Fléau (autrefois royaume de Lordaeron, Chevaliers de la Main d'argent)]=],
	aliases = { "Arthas", "prince Arthas" },
	sections = {
		{
			title = "Résumé",
			text = [=[Arthas Menethil était le prince héritier de {link:lordaeron}Lordaeron{/link}, un chevalier de la Main d'argent et l'élève d'{link:uther-the-lightbringer}Uther le Porteur de Lumière{/link}. Il était brave, aimé et fier. Il partit sauver son peuple d'une peste de non-mort, et il finit par le détruire. Il assassina son père, le roi {link:terenas-menethil}Terenas Menethil{/link}, et mena le {link:scourge}Fléau{/link} à travers le nord. Il règne aujourd'hui sur les morts-vivants depuis le cœur gelé de {red:northrend}Norfendre{/red}.]=],
		},
		{
			title = "Importance",
			text = [=[Aucune chute dans l'histoire de l'humanité ne fut si grande ni si terrible. Le nom d'Arthas est maudit dans toutes les terres qui connurent jadis l'{link:alliance}Alliance{/link}, et les terres qu'il dévasta s'appellent toujours les {link:eastern-plaguelands}Maleterres{/link}.]=],
		},
		{
			title = "Le prince",
			text = [=[Arthas était le fils unique de {link:terenas-menethil}Terenas{/link}. {link:uther-the-lightbringer}Uther{/link} le forma comme paladin de la {link:holy-light}Lumière sacrée{/link}, et il fut accueilli dans l'ordre de la Main d'argent. Quand une peste frappa les terres agricoles du nord de {link:lordaeron}Lordaeron{/link}, le roi envoya Arthas et Uther y mettre fin. Avec {link:jaina-proudmoore}Jaina Proudmoore{/link}, de {link:dalaran}Dalaran{/link}, à ses côtés, Arthas remonta la maladie jusqu'au nécromancien {link:kel-thuzad}Kel'Thuzad{/link} et son {link:cult-of-the-damned}culte des Damnés{/link}, et le tua. Pourtant, la peste continuait de se répandre. À Stratholme, Arthas découvrit que le grain de la cité était contaminé, et que tous ceux qui en avaient mangé se relèveraient en morts-vivants. Il ordonna que la cité soit purgée. Uther et Jaina refusèrent d'y prendre part, et Arthas mena l'{link:culling-of-stratholme}Épuration de Stratholme{/link} sans eux.]=],
		},
		{
			title = "La chute",
			text = [=[Arthas poursuivit le seigneur de l'effroi Mal'Ganis jusqu'en Norfendre. Là, il brûla ses propres navires pour que ses hommes ne puissent faire demi-tour, et il prit la lame runique maudite {red:frostmourne}Deuillegivre{/red}. Avec elle, il tua Mal'Ganis, mais l'épée réclama son âme. Il rentra en {link:lordaeron}Lordaeron{/link} en serviteur du {red:lich-king}roi-liche{/red}. Dans la salle du trône, il assassina son père, et le royaume tomba. Il détruisit l'ordre de la Main d'argent, tua {link:uther-the-lightbringer}Uther{/link}, et releva {link:kel-thuzad}Kel'Thuzad{/link} auprès du puits de Soleil après avoir dévasté {link:quel-thalas}Quel'Thalas{/link}. Il tua la générale des forestiers {link:sylvanas-windrunner}Sylvanas Windrunner{/link} et lia son esprit à sa volonté.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il mena l'{link:culling-of-stratholme}Épuration de Stratholme{/link}.
• Il assassina le {link:terenas-menethil}roi Terenas{/link} et livra {link:lordaeron}Lordaeron{/link} au {link:scourge}Fléau{/link}.
• Il tua {link:uther-the-lightbringer}Uther le Porteur de Lumière{/link}.
• Il ravagea {link:quel-thalas}Quel'Thalas{/link} et souilla le puits de Soleil pour relever {link:kel-thuzad}Kel'Thuzad{/link} sous la forme d'une liche.
• Il ouvrit à la {link:burning-legion}Légion ardente{/link} le chemin de {link:dalaran}Dalaran{/link}.]=],
		},
		{
			title = "Destin",
			text = [=[Après la {link:battle-of-mount-hyjal}bataille du mont Hyjal{/link}, la puissance du roi-liche déclina, et Arthas perdit son emprise sur {link:lordaeron}Lordaeron{/link}. {link:sylvanas-windrunner}Sylvanas{/link} se libéra de son contrôle, et les {link:forsaken}Réprouvés{/link} se dressèrent contre lui. Appelé par son maître, Arthas retourna en Norfendre. Sur le glacier de la Couronne de glace, il combattit et vainquit {link:illidan-stormrage}Illidan Stormrage{/link}. Puis il gravit le Trône de glace et coiffa le heaume du roi-liche, et les deux ne firent plus qu'un. Arthas règne désormais comme roi-liche en Norfendre. En Lordaeron, {link:kel-thuzad}Kel'Thuzad{/link} commande le {link:scourge}Fléau{/link} en son nom. {link:muradin-bronzebeard}Muradin Bronzebeard{/link}, qui l'avait jadis suivi dans le nord, ne revint jamais.]=],
		},
	},
	bonds = {
		{ id = "terenas-menethil", name = "Terenas Menethil", note = "son père, et sa victime" },
		{ id = "uther-the-lightbringer", name = "Uther le Porteur de Lumière", note = "son maître, et sa victime" },
		{ id = "jaina-proudmoore", name = "Jaina Proudmoore", note = "son amour perdu" },
		{ id = "kel-thuzad", name = "Kel'Thuzad", note = "son ennemi, puis son serviteur" },
		{ id = "ner-zhul", name = "Ner'zhul", note = "le roi-liche auquel il s'unit" },
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "son ennemi à la Couronne de glace" },
		{ id = "sylvanas-windrunner", name = "Sylvanas Windrunner", note = "sa victime et son ennemie" },
	},
})

Translate("frFR", "uther-the-lightbringer", {
	title = "Uther le Porteur de Lumière",
	subtitle = "Le premier des paladins",
	allegiance = "Chevaliers de la Main d'argent · Église de la Lumière sacrée",
	aliases = { "Uther", "seigneur Uther" },
	sections = {
		{
			title = "Résumé",
			text = [=[Uther le Porteur de Lumière fut le premier paladin de la {link:holy-light}Lumière sacrée{/link} et le chef des Chevaliers de la Main d'argent. Il apprit sa foi aux côtés de l'archevêque {link:alonsus-faol}Alonsus Faol{/link}, combattit la {link:horde}Horde{/link} à travers le nord pendant la {link:second-war}Deuxième Guerre{/link} et forma le prince {link:arthas-menethil}Arthas Menethil{/link}. Il fut le maître et l'ami du prince, et il mourut de sa main.]=],
		},
		{
			title = "Importance",
			text = [=[Uther montra aux royaumes humains que la foi et l'acier pouvaient aller de pair. L'ordre qu'il dirigeait défendit {link:lordaeron}Lordaeron{/link} pendant une génération, et son nom est encore prononcé avec révérence par chaque paladin du monde.]=],
		},
		{
			title = "La Main d'argent",
			text = [=[Après la {link:first-war}Première Guerre{/link}, la nouvelle parvint dans le nord que la {link:horde}Horde{/link} avait massacré les clercs de l'{link:northshire-abbey}abbaye de Northshire{/link}. {link:alonsus-faol}Alonsus Faol{/link} résolut que les serviteurs de la Lumière ne resteraient plus sans défense. Avec la bénédiction d'{link:anduin-lothar}Anduin Lothar{/link}, il rassembla des guerriers à la foi solide et leur apprit à manier la puissance sacrée au combat. Uther fut le premier d'entre eux. Quand leur formation fut achevée, l'archevêque le nomma chef des nouveaux Chevaliers de la Main d'argent. Uther et ses paladins, parmi lesquels {link:turalyon}Turalyon{/link} et {link:tirion-fordring}Tirion Fordring{/link}, combattirent tout au long de la {link:second-war}Deuxième Guerre{/link} et apportèrent guérison et espoir là où les combats étaient les plus durs.]=],
		},
		{
			title = "Le prince",
			text = [=[Dans les années de paix, Uther prit le jeune {link:arthas-menethil}Arthas{/link} pour élève et l'accueillit dans l'ordre. Quand une peste éclata dans le nord de {link:lordaeron}Lordaeron{/link}, le roi {link:terenas-menethil}Terenas Menethil{/link} les envoya tous deux y mettre fin. À Stratholme, Arthas ordonna que les habitants de la cité soient tués avant que la peste ne puisse les relever. Uther refusa. Il ne voulait pas frapper les vivants, et Arthas le renvoya de son service. L'{link:culling-of-stratholme}Épuration de Stratholme{/link} se fit sans lui.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il fut le premier paladin ordonné par {link:alonsus-faol}Alonsus Faol{/link} et dirigea les Chevaliers de la Main d'argent.
• Il combattit la {link:horde}Horde{/link} pendant la {link:second-war}Deuxième Guerre{/link}.
• Il forma le {link:arthas-menethil}prince Arthas{/link} aux voies de la Lumière.
• Il refusa de prendre part à l'{link:culling-of-stratholme}Épuration de Stratholme{/link}.]=],
		},
		{
			title = "Destin",
			text = [=[Quand {link:arthas-menethil}Arthas{/link} revint de {red:northrend}Norfendre{/red} et assassina son père, le prince se retourna contre l'ordre qui l'avait élevé. Il brisa la Main d'argent et traqua ses chevaliers. Uther et ses derniers paladins gardaient l'urne qui contenait les cendres du {link:terenas-menethil}roi Terenas{/link}. Arthas vint la prendre, et l'élève tua son maître avec la lame runique {red:frostmourne}Deuillegivre{/red}. Un tombeau se dresse aujourd'hui à la mémoire d'Uther dans les {link:western-plaguelands}Maleterres de l'ouest{/link}, un lieu de deuil dans une terre morte. Certains des paladins qu'il forma vivent encore, et ils se souviennent de lui.]=],
		},
	},
	bonds = {
		{ id = "alonsus-faol", name = "Alonsus Faol", note = "son mentor" },
		{ id = "arthas-menethil", name = "Arthas Menethil", note = "son élève, et son meurtrier" },
		{ id = "terenas-menethil", name = "Terenas Menethil", note = "son roi" },
		{ id = "turalyon", name = "Turalyon", note = "un frère de la Main d'argent" },
		{ id = "tirion-fordring", name = "Tirion Fordring", note = "un frère de la Main d'argent" },
	},
})

Translate("frFR", "alonsus-faol", {
	title = "Alonsus Faol",
	subtitle = "Archevêque de la Lumière sacrée",
	allegiance = "Église de la Lumière sacrée · Chevaliers de la Main d'argent",
	aliases = { "Archevêque Faol", "archevêque Alonsus Faol" },
	sections = {
		{
			title = "Résumé",
			text = [=[Alonsus Faol était l'archevêque de l'Église de la {link:holy-light}Lumière sacrée{/link}, le père spirituel des royaumes humains à l'époque de la {link:second-war}Deuxième Guerre{/link}. C'était un vieil homme petit et trapu, à la barbe blanche et au visage bienveillant, aimé des gens du peuple comme des rois. Il fonda les Chevaliers de la Main d'argent et ordonna {link:uther-the-lightbringer}Uther le Porteur de Lumière{/link} premier des paladins.]=],
		},
		{
			title = "Importance",
			text = [=[Avant Faol, les serviteurs de la Lumière guérissaient et priaient pendant que d'autres combattaient. Après lui, ils partirent en guerre. Les ordres de paladins de toutes les terres humaines, et les jeunes paladins formés aujourd'hui à l'{link:northshire-abbey}abbaye de Northshire{/link}, suivent tous la voie qu'il ouvrit.]=],
		},
		{
			title = "La Main d'argent",
			text = [=[Faol servait la foi depuis longtemps, et il avait pris le jeune {link:uther-the-lightbringer}Uther{/link} pour apprenti bien des années avant l'arrivée des orcs. Pendant la {link:first-war}Première Guerre{/link}, la {link:horde}Horde{/link} incendia l'abbaye de {link:northshire-abbey}Northshire{/link} et massacra ses clercs. Quand les survivants de {link:stormwind-city}Stormwind{/link} atteignirent {link:lordaeron}Lordaeron{/link}, l'archevêque apprit le massacre, et il résolut que cela ne se reproduirait pas. Avec {link:anduin-lothar}Anduin Lothar{/link}, il fonda un ordre de guerriers saints. Il choisit des chevaliers à la foi solide et leur apprit à invoquer la Lumière au combat. Uther, {link:turalyon}Turalyon{/link}, {link:tirion-fordring}Tirion Fordring{/link} et quelques autres furent les premiers. Quand leur formation fut achevée, Faol nomma Uther chef des Chevaliers de la Main d'argent.]=],
		},
		{
			title = "La paix",
			text = [=[Faol était présent quand les seigneurs des nations humaines se réunirent dans la capitale de {link:lordaeron}Lordaeron{/link}. On dit qu'il aida à calmer les esprits quand leurs querelles s'échauffaient. Après la guerre, il tourna ses soins vers la reconstruction du sud. Il envoya ses prêtres et ses paladins partout où l'on avait besoin d'eux, et il soutint l'érection de la nouvelle cathédrale de la Lumière à {link:stormwind-city}Stormwind{/link} et la restauration de {link:northshire-abbey}Northshire{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il forma {link:uther-the-lightbringer}Uther{/link} à la foi de la Lumière.
• Il fonda les Chevaliers de la Main d'argent avec {link:anduin-lothar}Anduin Lothar{/link}.
• Il ordonna les premiers paladins et nomma Uther leur chef.
• Il conseilla les seigneurs de l'{link:alliance}Alliance{/link} pendant la {link:second-war}Deuxième Guerre{/link}.
• Il contribua à la reconstruction de {link:stormwind-city}Stormwind{/link} et de l'abbaye de {link:northshire-abbey}Northshire{/link}.]=],
		},
		{
			title = "Destin",
			text = [=[Faol mourut dans les années qui suivirent la {link:second-war}Deuxième Guerre{/link}. Les chroniques ne disent pas comment. Son élève {link:archbishop-benedictus}Benedictus{/link} lui succéda comme archevêque, et garde toujours la cathédrale de la Lumière à {link:stormwind-city}Stormwind{/link}. Faol fut inhumé dans les {link:tirisfal-glades}Clairières de Tirisfal{/link}, dans un tombeau appelé le Repos de Faol. Cette terre appartient aujourd'hui aux morts-vivants, et les {link:forsaken}Réprouvés{/link} marchent là où les fidèles venaient jadis prier.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucune chronique ne dit comment ni quand mourut Alonsus Faol. Elles ne consignent pas non plus grand-chose de sa vie avant qu'il ne devienne archevêque.]=],
		},
	},
	bonds = {
		{ id = "uther-the-lightbringer", name = "Uther le Porteur de Lumière", note = "son apprenti" },
		{ id = "anduin-lothar", name = "Anduin Lothar", note = "fonda la Main d'argent avec lui" },
		{ id = "terenas-menethil", name = "Terenas Menethil", note = "son roi en Lordaeron" },
	},
})

Translate("frFR", "orgrim-doomhammer", {
	title = "Orgrim Doomhammer",
	subtitle = "Chef de guerre de la Horde pendant la Deuxième Guerre",
	allegiance = "Horde · clan Blackrock",
	aliases = { "Orgrim", "chef de guerre Doomhammer" },
	sections = {
		{
			title = "Résumé",
			text = [=[Orgrim Doomhammer fut le chef de guerre de la {link:horde}Horde{/link} qui conquit {link:stormwind-city}Stormwind{/link} et mena les orcs pendant la {link:second-war}Deuxième Guerre{/link}. C'était un guerrier du {link:blackrock-clan}clan Blackrock{/link}, le porteur du grand marteau de sa famille, et le plus vieil ami de Durotan des {link:frostwolf-clan}Frostwolf{/link}. Il haïssait les démonistes qui avaient corrompu son peuple, et il tenta, à sa manière, de le libérer. À la fin de sa vie, il trouva l'{link:orcs}orc{/link} qui achèverait cette œuvre : {link:thrall}Thrall{/link}.]=],
		},
		{
			title = "Importance",
			text = [=[Doomhammer fit de la {link:horde}Horde{/link} une seule armée animée d'une seule volonté. Sous ses ordres, elle fut plus près que jamais de conquérir les royaumes humains. Pourtant, son plus grand héritage n'est pas une conquête. C'est la nouvelle Horde, et sa capitale d'{link:orgrimmar}Orgrimmar{/link} porte son nom.]=],
		},
		{
			title = "La Première Guerre",
			text = [=[Dans les premières années de la guerre, Orgrim servit comme second du chef de guerre Blackhand, une marionnette du démoniste {link:gul-dan}Gul'dan{/link}. Quand Durotan fut assassiné par les tueurs de Gul'dan, la colère d'Orgrim ne put plus être contenue. Après la mort de {link:medivh}Medivh{/link}, il défia Blackhand en duel à mort et lui broya le crâne avec le Marteau-du-destin. Devenu chef de guerre, il interdit la magie noire qui avait empoisonné Draenor. Il mena de nouveau la {link:horde}Horde{/link} contre {link:stormwind-city}Stormwind{/link}, et cette fois la cité tomba. Il découvrit ensuite le repaire du {link:shadow-council}Conseil des ombres{/link} des démonistes et massacra la plupart de ses membres.]=],
		},
		{
			title = "La Deuxième Guerre",
			text = [=[Doomhammer épargna {link:gul-dan}Gul'dan{/link}, qui lui promit de nouvelles armes. Il rassembla toute la puissance de la {link:horde}Horde{/link} et marcha vers le nord. Il prit les {link:kingdom-of-ironforge}terres naines{/link} de Khaz Modan, s'allia aux trolls des forêts amani, et lança au combat les dragons rouges du {link:dragonmaw-clan}clan Dragonmaw{/link}. Ses armées incendièrent les forêts de {link:quel-thalas}Quel'Thalas{/link} et assiégèrent la capitale de {link:lordaeron}Lordaeron{/link}. Puis Gul'dan le trahit et emmena une grande partie de la Horde. Le siège échoua. Au {link:blackrock-mountain}Mont Blackrock{/link}, Doomhammer tua {link:anduin-lothar}Anduin Lothar{/link} au combat, mais le paladin {link:turalyon}Turalyon{/link} rallia l'{link:alliance}Alliance{/link}, et la Horde fut écrasée.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il tua Blackhand et se fit chef de guerre.
• Il conquit {link:stormwind-city}Stormwind{/link} et mit fin à la {link:first-war}Première Guerre{/link}.
• Il détruisit {link:shadow-council}le Conseil{/link} des ombres.
• Il mena la {link:horde}Horde{/link} jusqu'aux portes de la capitale de {link:lordaeron}Lordaeron{/link}.
• Il tua {link:anduin-lothar}Anduin Lothar{/link} au {link:blackrock-mountain}Mont Blackrock{/link}.]=],
		},
		{
			title = "Destin",
			text = [=[Doomhammer fut fait prisonnier et exhibé enchaîné dans la capitale de {link:lordaeron}Lordaeron{/link}. Il s'évada et vécut caché pendant de nombreuses années. Quand le jeune {link:thrall}Thrall{/link}, fils de Durotan, vint le chercher, le vieux chef de guerre le reconnut aussitôt. Il se joignit à Thrall pour libérer les orcs des camps d'internement, et il tomba lors de l'une de ces batailles, dans les collines des {link:hillsbrad-foothills}Contreforts d'Hillsbrad{/link}. Avant de mourir, il nomma Thrall nouveau chef de guerre. Thrall porte aujourd'hui l'armure noire de Doomhammer et son marteau à {link:orgrimmar}Orgrimmar{/link}.]=],
		},
	},
	bonds = {
		{ id = "thrall", name = "Thrall", note = "son héritier comme chef de guerre" },
		{ id = "gul-dan", name = "Gul'dan", note = "le démoniste qu'il méprisait" },
		{ id = "anduin-lothar", name = "Anduin Lothar", note = "l'ennemi qu'il tua" },
		{ id = "llane-wrynn", name = "Llane Wrynn", note = "le roi dont il prit la cité" },
		{ id = "grom-hellscream", name = "Grom Hellscream", note = "un autre chef de clan" },
	},
})

Translate("frFR", "grom-hellscream", {
	title = "Grom Hellscream",
	subtitle = "Chef des Warsong",
	allegiance = "Horde · clan Warsong",
	aliases = { "Grommash", "Grommash Hellscream" },
	sections = {
		{
			title = "Résumé",
			text = [=[Grom Hellscream était le chef du clan Warsong, le plus féroce des seigneurs de guerre {link:orcs}orcs{/link} et l'ami le plus fidèle de {link:thrall}Thrall{/link}. Il fut le premier orc à boire le sang du démon {link:mannoroth}Mannoroth{/link}, et lia ainsi son peuple à la {link:burning-legion}Légion ardente{/link}. Il fut aussi l'orc qui brisa ce lien, au prix de sa propre vie.]=],
		},
		{
			title = "Importance",
			text = [=[La malédiction des orcs commença avec Grom et s'acheva avec lui. Sa mort en {link:ashenvale}Orneval{/link} libéra les orcs du sang démoniaque, et la {link:horde}Horde{/link} d'aujourd'hui doit sa liberté à son dernier combat.]=],
		},
		{
			title = "La malédiction du sang",
			text = [=[Sur {red:draenor}Draenor{/red}, le démoniste {link:gul-dan}Gul'dan{/link} rassembla les chefs des clans et leur offrit un breuvage du sang de {link:mannoroth}Mannoroth{/link}. Grom fut le premier à boire, et les autres suivirent. Le sang emplit les orcs d'une rage terrible et les lia à la volonté de la Légion. Quand la {link:horde}Horde{/link} marcha sur {link:azeroth}Azeroth{/link}, Gul'dan s'arrangea pour garder Grom et ses Warsong sur Draenor. Ils ne prirent aucune part à la {link:second-war}Deuxième Guerre{/link}. Après la guerre, ils franchirent la {link:dark-portal}Porte des Ténèbres{/link} et combattirent pour elle jusqu'à sa destruction, et ils restèrent bloqués sur les terres des humains.]=],
		},
		{
			title = "La léthargie",
			text = [=[Pendant de nombreuses années, les Warsong vécurent cachés dans les terres sauvages de {link:lordaeron}Lordaeron{/link}. Comme tous les orcs, Grom souffrait de la perte de la fureur démoniaque. Pourtant, il combattit la léthargie avec une volonté de fer. Quand le jeune {link:thrall}Thrall{/link} vint le chercher, Grom vit en lui l'espoir de son peuple. Il se joignit à Thrall pour libérer les orcs des camps d'internement. Il fut capturé par les humains à la veille de la {link:third-war}Troisième Guerre{/link}, et Thrall le libéra de nouveau.]=],
		},
		{
			title = "Kalimdor",
			text = [=[Les orcs firent voile vers l'ouest jusqu'en {link:kalimdor}Kalimdor{/link}. Là, les Warsong furent envoyés dans les forêts d'{link:ashenvale}Orneval{/link} pour couper du bois, et ils en vinrent aux mains avec les {link:night-elves}elfes de la nuit{/link}. Le demi-dieu {link:cenarius}Cenarius{/link} vint défendre la forêt. Désespérant de vaincre, Grom et ses guerriers burent à une source que {link:mannoroth}Mannoroth{/link} avait souillée de son sang. L'ancienne malédiction revint. Dans cette fureur, Grom tua Cenarius. {link:thrall}Thrall{/link}, aidé de {link:jaina-proudmoore}Jaina Proudmoore{/link}, captura son ami et le purifia de la rage.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il fut le premier {link:orcs}orc{/link} à boire le sang de {link:mannoroth}Mannoroth{/link}.
• Il tint la {link:dark-portal}Porte des Ténèbres{/link} contre l'{link:alliance}Alliance{/link} après la {link:second-war}Deuxième Guerre{/link}.
• Il résista à la léthargie des orcs pendant des années de clandestinité.
• Il aida {link:thrall}Thrall{/link} à libérer les orcs des camps.
• Il tua {link:cenarius}Cenarius{/link}, puis tua Mannoroth.]=],
		},
		{
			title = "Destin",
			text = [=[Grom et {link:thrall}Thrall{/link} se rendirent ensemble dans le canyon où les attendait {link:mannoroth}Mannoroth{/link}. Thrall tomba sous la puissance du démon. Grom chargea seul, planta sa hache dans la poitrine de Mannoroth et le tua. La mort du démon libéra les orcs de la malédiction du sang. Grom mourut de ses blessures dans les bras de Thrall. Son clan coupe toujours les arbres d'{link:ashenvale}Orneval{/link} au nom de la {link:horde}Horde{/link}, et les elfes de la nuit leur disputent toujours chaque arbre.]=],
		},
	},
	bonds = {
		{ id = "thrall", name = "Thrall", note = "son chef de guerre et ami" },
		{ id = "gul-dan", name = "Gul'dan", note = "lui donna le sang du démon" },
		{ id = "orgrim-doomhammer", name = "Orgrim Doomhammer", note = "un autre chef de clan" },
		{ id = "archimonde", name = "Archimonde", note = "le maître du démon qu'il tua" },
		{ id = "jaina-proudmoore", name = "Jaina Proudmoore", note = "aida à le libérer" },
	},
})

Translate("frFR", "gul-dan", {
	title = "Gul'dan",
	subtitle = "Le traître des orcs",
	allegiance = "Conseil des ombres · clan Stormreaver",
	sections = {
		{
			title = "Résumé",
			text = [=[Gul'dan fut le premier démoniste {link:orcs}orc{/link} et l'architecte de l'ancienne {link:horde}Horde{/link}. Il avait été l'apprenti du chaman {link:ner-zhul}Ner'zhul{/link}. Il vendit son peuple à la {link:burning-legion}Légion ardente{/link} en échange du pouvoir, et il empoisonna à la fois sa race et son monde. Il ouvrit la {link:dark-portal}Porte des Ténèbres{/link} avec {link:medivh}Medivh{/link} et dirigea les maîtres cachés de la Horde, {link:shadow-council}le Conseil{/link} des ombres. À la fin, il trahit la Horde elle-même.]=],
		},
		{
			title = "Importance",
			text = [=[Une grande part des souffrances des orcs, et des peuples qu'ils combattirent, remonte à l'ambition de Gul'dan. Sa {link:fel-magic}magie gangrenée{/link} vida {red:draenor}Draenor{/red} de sa vie. Son sang démoniaque fit des orcs les esclaves de leur rage. Sa trahison coûta à la {link:horde}Horde{/link} la {link:second-war}Deuxième Guerre{/link}.]=],
		},
		{
			title = "Le Conseil des ombres",
			text = [=[Sur Draenor, le seigneur démon {link:kil-jaeden}Kil'jaeden{/link} cherchait un serviteur parmi les orcs. Quand {link:ner-zhul}Ner'zhul{/link} commença à douter du démon, Kil'jaeden se tourna vers Gul'dan, qui n'avait aucun doute. Kil'jaeden lui enseigna les arts de la sorcellerie gangrenée. Gul'dan fonda {link:shadow-council}le Conseil{/link} des ombres, un cercle de démonistes qui gouvernait les clans derrière un chef de guerre fantoche, Blackhand. Il offrit aux chefs de clan le sang de {link:mannoroth}Mannoroth{/link}, et ils burent. Puis une voix venue d'un autre monde l'atteignit. C'était {link:medivh}Medivh{/link}, et ensemble ils ouvrirent la {link:dark-portal}Porte des Ténèbres{/link} vers {link:azeroth}Azeroth{/link}.]=],
		},
		{
			title = "Les guerres",
			text = [=[À la fin de la {link:first-war}Première Guerre{/link}, Gul'dan tenta d'arracher les secrets de la tombe de {link:sargeras}Sargeras{/link} à l'esprit mourant de {link:medivh}Medivh{/link}. L'effort le plongea dans une longue torpeur. Pendant son sommeil, {link:orgrim-doomhammer}Orgrim Doomhammer{/link} tua Blackhand et détruisit la plus grande partie du {link:shadow-council}Conseil des ombres{/link}. Quand Gul'dan s'éveilla, il acheta sa vie par la promesse de nouvelles armes. Lui et ses démonistes levèrent les premiers chevaliers de la mort de la {link:horde}Horde{/link}. Pourtant, sa loyauté n'était qu'un masque. Tandis que Doomhammer assiégeait la capitale de {link:lordaeron}Lordaeron{/link}, Gul'dan emmena ses partisans et prit la mer pour chercher la tombe de Sargeras sous les flots.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il fonda {link:shadow-council}le Conseil{/link} des ombres et gouverna la {link:horde}Horde{/link} par l'intermédiaire de Blackhand.
• Il donna aux chefs de clan le sang de {link:mannoroth}Mannoroth{/link}.
• Il ouvrit la {link:dark-portal}Porte des Ténèbres{/link} avec {link:medivh}Medivh{/link}.
• Il leva les premiers chevaliers de la mort de la Horde.
• Il abandonna Doomhammer aux portes de la capitale de {link:lordaeron}Lordaeron{/link}.]=],
		},
		{
			title = "Destin",
			text = [=[Gul'dan fit surgir la tombe de {link:sargeras}Sargeras{/link} des profondeurs de la Grande mer et y entra, espérant s'emparer de la puissance d'un dieu. Les démons qui la gardaient le mirent en pièces. Les guerriers de Doomhammer, envoyés pour punir sa trahison, massacrèrent ses partisans. Sans eux, la {link:horde}Horde{/link} ne put maintenir le siège, et elle fut repoussée jusqu'à la défaite. Le {link:skull-of-gul-dan}crâne de Gul'dan{/link} lui survécut, et il porta une sombre puissance à lui jusqu'à sa destruction pendant la {link:third-war}Troisième Guerre{/link}.]=],
		},
	},
	bonds = {
		{ id = "ner-zhul", name = "Ner'zhul", note = "son premier maître" },
		{ id = "medivh", name = "Medivh", note = "ouvrit la Porte des Ténèbres avec lui" },
		{ id = "orgrim-doomhammer", name = "Orgrim Doomhammer", note = "le chef de guerre qu'il trahit" },
		{ id = "grom-hellscream", name = "Grom Hellscream", note = "le premier à boire son sang" },
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "prit la puissance de son crâne" },
	},
})

Translate("frFR", "ner-zhul", {
	title = "Ner'zhul",
	subtitle = "Ancien chaman des Shadowmoon",
	allegiance = "clan Shadowmoon · Fléau",
	sections = {
		{
			title = "Résumé",
			text = [=[Ner'zhul était l'ancien chaman du clan Shadowmoon et le chef spirituel le plus respecté des orcs de {red:draenor}Draenor{/red}. Le seigneur démon {link:kil-jaeden}Kil'jaeden{/link} le trompa et se servit de lui pour dresser les orcs contre les draeneï. Plus tard, Ner'zhul déchira son propre monde en tentant de le fuir. Capturé par les démons, il fut fait {red:lich-king}roi-liche{/red}, maître du {link:scourge}Fléau{/link}.]=],
		},
		{
			title = "Importance",
			text = [=[Ner'zhul apporta la ruine deux fois. En tant que chaman, il ouvrit le cœur de son peuple à la {link:burning-legion}Légion ardente{/link}. En tant que roi-liche, il envoya une peste de non-mort sur {link:lordaeron}Lordaeron{/link}. La {link:third-war}Troisième Guerre{/link} et les terres mortes du nord sont son œuvre autant que celle de quiconque.]=],
		},
		{
			title = "Le trompé",
			text = [=[Dans les anciens temps de Draenor, les orcs vivaient en clans de chasseurs et de chamans. Ner'zhul parlait pour les esprits parmi eux. Puis {link:kil-jaeden}Kil'jaeden{/link} vint à lui, déguisé en esprit des ancêtres, et lui murmura que les paisibles draeneï complotaient contre les orcs. Ner'zhul le crut et mena son peuple à la guerre. Ce n'est que plus tard qu'il vit la vérité, et quand il refusa d'aller plus loin, Kil'jaeden se tourna à sa place vers son apprenti, {link:gul-dan}Gul'dan{/link}. Ner'zhul fut écarté et vécut dans la honte tandis que la {link:horde}Horde{/link} marchait sur {link:azeroth}Azeroth{/link}.]=],
		},
		{
			title = "L'éclatement",
			text = [=[Après la {link:second-war}Deuxième Guerre{/link}, les orcs restés sur Draenor se rassemblèrent autour du vieux chaman. Il rouvrit la {link:dark-portal}Porte des Ténèbres{/link} et envoya des guerriers voler de puissantes reliques sur {link:azeroth}Azeroth{/link}, dans le but d'ouvrir à son peuple des portails vers de nouveaux mondes. L'{link:alliance}Alliance{/link} envoya une expédition à travers la Porte pour l'arrêter. Ner'zhul ouvrit malgré tout ses portails. Les énergies déchirèrent Draenor, et il s'enfuit par une faille avec ses partisans.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il guida les orcs en tant que leur plus grand chaman.
• Il mena les clans contre les draeneï, trompé par {link:kil-jaeden}Kil'jaeden{/link}.
• Il rouvrit la {link:dark-portal}Porte des Ténèbres{/link} après la {link:second-war}Deuxième Guerre{/link}.
• Il fit éclater Draenor avec ses portails.
• En tant que roi-liche, il leva le {link:scourge}Fléau{/link} et déchaîna la peste sur {link:lordaeron}Lordaeron{/link}.]=],
		},
		{
			title = "Destin",
			text = [=[{link:kil-jaeden}Kil'jaeden{/link} l'attendait au-delà de la faille. Le démon arracha la chair du corps du chaman et lia son esprit à une armure et à un heaume. Il scella Ner'zhul dans un bloc de glace et le jeta sur {link:azeroth}Azeroth{/link}. Le bloc tomba sur le glacier de la Couronne de glace, en {red:northrend}Norfendre{/red}, et c'est là qu'il devint le roi-liche. Depuis le Trône de glace, il leva le {link:scourge}Fléau{/link}. Il appela {link:kel-thuzad}Kel'Thuzad{/link} à son service et envoya la peste vers le sud. Il finit par s'emparer du prince {link:arthas-menethil}Arthas Menethil{/link} au moyen de la lame runique {red:frostmourne}Deuillegivre{/red}. Quand sa puissance déclina, il appela Arthas à la Couronne de glace, et le prince coiffa son heaume. Ner'zhul et Arthas ne font désormais plus qu'un, et le roi-liche règne dans le nord.]=],
		},
	},
	bonds = {
		{ id = "gul-dan", name = "Gul'dan", note = "son apprenti, et son usurpateur" },
		{ id = "arthas-menethil", name = "Arthas Menethil", note = "le prince dont il s'empara et auquel il s'unit" },
		{ id = "kel-thuzad", name = "Kel'Thuzad", note = "son serviteur" },
		{ id = "grom-hellscream", name = "Grom Hellscream", note = "chef de clan de sa Horde" },
	},
})

Translate("frFR", "archimonde", {
	title = "Archimonde",
	subtitle = "Le Profanateur",
	allegiance = "Légion ardente",
	sections = {
		{
			title = "Résumé",
			text = [=[Archimonde le Profanateur était l'un des grands seigneurs de la {link:burning-legion}Légion ardente{/link}, second seulement après son sombre maître, {link:sargeras}Sargeras{/link}. Il avait été l'un des chefs des érédars, un peuple fier d'un autre monde, jusqu'à ce que Sargeras leur offre la puissance et qu'il accepte. Il mena les guerres de la Légion à travers d'innombrables mondes. Sur {link:azeroth}Azeroth{/link}, il fut plus près qu'aucun démon avant lui de dévorer le monde, et il mourut au pied de l'Arbre-Monde.]=],
		},
		{
			title = "Importance",
			text = [=[L'invasion d'Archimonde pendant la {link:third-war}Troisième Guerre{/link} fut le plus grand assaut démoniaque que le monde ait connu depuis la {link:war-of-the-ancients}guerre des Anciens{/link}. Sa défaite au {link:mount-hyjal}mont Hyjal{/link} scella une paix fragile entre {link:orcs}orcs{/link}, {link:humans}humains{/link} et {link:night-elves}elfes de la nuit{/link}, une paix qui a façonné {link:kalimdor}Kalimdor{/link} depuis.]=],
		},
		{
			title = "Les érédars",
			text = [=[Il y a longtemps, les érédars étaient gouvernés par trois chefs : Archimonde, {link:kil-jaeden}Kil'jaeden{/link} et Velen. {link:sargeras}Sargeras{/link} vint à eux avec une offre de savoir et de puissance. Archimonde et Kil'jaeden acceptèrent, et ils furent changés en démons. Velen refusa et s'enfuit avec ses fidèles. Archimonde devint l'un des plus grands lieutenants de Sargeras. Pendant la guerre des Anciens, il y a dix mille ans, la Légion vint sur {link:azeroth}Azeroth{/link} par le {link:well-of-eternity}puits d'Éternité{/link}. Elle fut repoussée quand le Puits fut détruit.]=],
		},
		{
			title = "La Troisième Guerre",
			text = [=[La Légion revint bien des âges plus tard. Quand le {link:scourge}Fléau{/link} eut ravagé {link:lordaeron}Lordaeron{/link}, la liche {link:kel-thuzad}Kel'Thuzad{/link} se servit du grimoire de {link:medivh}Medivh{/link} pour invoquer Archimonde dans la cité de {link:dalaran}Dalaran{/link}. Le seigneur démon détruisit la cité des mages d'un seul coup de sa puissance. Il mena ensuite la Légion en {link:kalimdor}Kalimdor{/link}, où les dernières eaux du {link:well-of-eternity}puits d'Éternité{/link} reposaient sous l'Arbre-Monde, {link:nordrassil}Nordrassil{/link}. Il voulait drainer sa puissance et consumer le monde.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il accepta l'offre de {link:sargeras}Sargeras{/link} et devint un seigneur de la Légion.
• Il fit la guerre à {link:azeroth}Azeroth{/link} pendant la guerre des Anciens.
• Il fut invoqué dans {link:dalaran}Dalaran{/link} par {link:kel-thuzad}Kel'Thuzad{/link} et la détruisit.
• Il marcha sur le mont Hyjal pour drainer la puissance de {link:nordrassil}Nordrassil{/link}.]=],
		},
		{
			title = "Destin",
			text = [=[Lors de la {link:battle-of-mount-hyjal}bataille du mont Hyjal{/link}, les orcs de {link:thrall}Thrall{/link}, les hommes de {link:jaina-proudmoore}Jaina Proudmoore{/link} et les elfes de la nuit de {link:tyrande-whisperwind}Tyrande Whisperwind{/link} et de {link:malfurion-stormrage}Malfurion Stormrage{/link} tinrent les pentes de la montagne aussi longtemps qu'ils le purent. Archimonde atteignit enfin l'Arbre-Monde. Malfurion sonna le Cor de {link:cenarius}Cenarius{/link}, et une vaste armée d'esprits des anciens assaillit le seigneur démon et le détruisit dans une grande explosion. La puissance de {link:nordrassil}Nordrassil{/link} fut épuisée, et les elfes de la nuit perdirent leur immortalité. Pourtant, l'invasion de la Légion était brisée. Ses démons s'attardent encore dans les bois corrompus de {link:felwood}Gangrebois{/link}, et son ombre n'a pas quitté le monde.]=],
		},
	},
	bonds = {
		{ id = "kel-thuzad", name = "Kel'Thuzad", note = "l'invoqua sur Azeroth" },
		{ id = "malfurion-stormrage", name = "Malfurion Stormrage", note = "causa sa destruction" },
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "son ennemi pendant la Troisième Guerre" },
		{ id = "queen-azshara", name = "Reine Azshara", note = "qui ouvrit jadis la voie à la Légion" },
		{ id = "grom-hellscream", name = "Grom Hellscream", note = "tua son serviteur Mannoroth" },
	},
})

Translate("frFR", "illidan-stormrage", {
	title = "Illidan Stormrage",
	subtitle = "Le Traître",
	allegiance = "Inconnue (autrefois la résistance kaldorei)",
	aliases = { "Illidan", "le Traître" },
	sections = {
		{
			title = "Résumé",
			text = [=[Illidan Stormrage était un sorcier {link:night-elves}elfe de la nuit{/link} du monde ancien, le frère jumeau de {link:malfurion-stormrage}Malfurion Stormrage{/link} et son rival pour l'amour de {link:tyrande-whisperwind}Tyrande Whisperwind{/link}. Il combattit la {link:burning-legion}Légion ardente{/link}, et il la servit aussi. Il fut emprisonné pendant dix mille ans et libéré pendant la {link:third-war}Troisième Guerre{/link}. Certains le disent héros et beaucoup le disent traître. Son propre peuple le nomma le Traître.]=],
		},
		{
			title = "Importance",
			text = [=[Les choix d'Illidan ont autant sauvé que menacé le monde. Dans les temps anciens, il porta les eaux du {link:well-of-eternity}puits d'Éternité{/link} jusqu'au {link:mount-hyjal}mont Hyjal{/link}, où elles reposent encore sous {link:nordrassil}Nordrassil{/link}. Pendant la {link:third-war}Troisième Guerre{/link}, il tua un seigneur de la Légion et prit sa puissance pour lui-même.]=],
		},
		{
			title = "La guerre des Anciens",
			text = [=[Illidan naquit avec des yeux d'ambre, une marque qui, disait-on, annonçait la grandeur. Il était attiré par la {link:arcane-magic}magie des arcanes{/link} comme son frère l'était par la voie de {link:cenarius}Cenarius{/link}. Pendant la {link:war-of-the-ancients}guerre des Anciens{/link}, il combattit aux côtés des elfes de la nuit contre la {link:queen-azshara}reine Azshara{/link} et ses alliés démoniaques. Pourtant, il devint jaloux de son frère et avide de puissance, et il alla finalement trouver {link:sargeras}Sargeras{/link} lui-même. Le seigneur démon lui brûla les yeux et lui donna une nouvelle vue. Quand le puits d'Éternité fut détruit, Illidan versa des fioles volées de ses eaux dans un lac au sommet du mont Hyjal, créant un nouveau Puits. {link:malfurion-stormrage}Malfurion{/link} jugea que c'était un crime. Il fit enchaîner son frère sous la terre, gardé par la geôlière Maiev Shadowsong.]=],
		},
		{
			title = "La Troisième Guerre",
			text = [=[Dix mille ans plus tard, le {link:scourge}Fléau{/link} et la Légion vinrent en {link:kalimdor}Kalimdor{/link}. Contre la loi de son peuple, {link:tyrande-whisperwind}Tyrande{/link} libéra Illidan pour qu'il les aide. Dans la forêt que l'on nomme aujourd'hui {link:felwood}Gangrebois{/link}, il absorba le crâne de {link:gul-dan}Gul'dan{/link}, prit la forme d'un démon et tua le seigneur de l'effroi {link:tichondrius}Tichondrius{/link}. {link:malfurion-stormrage}Malfurion{/link} le bannit des forêts des elfes de la nuit.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il combattit {link:azshara}Azshara{/link} pendant la guerre des Anciens.
• Il créa un nouveau puits d'Éternité au sommet du mont Hyjal.
• Il absorba le {link:skull-of-gul-dan}crâne de Gul'dan{/link} et tua {link:tichondrius}Tichondrius{/link}.
• Il leva les nagas des profondeurs pour le servir après la {link:third-war}Troisième Guerre{/link}.]=],
		},
		{
			title = "Destin",
			text = [=[Après son bannissement, Illidan rassembla les {link:naga}nagas{/link} et chercha la tombe de {link:sargeras}Sargeras{/link} sous la mer. Il fut poursuivi par Maiev, par son frère et par {link:tyrande-whisperwind}Tyrande{/link}, et il leur échappa à tous. Plus tard, il marcha sur {red:northrend}Norfendre{/red} pour frapper le {red:lich-king}roi-liche{/red}. Sur le glacier de la Couronne de glace, il combattit {link:arthas-menethil}Arthas Menethil{/link} et fut vaincu. Il s'enfuit avec ses partisans survivants. Où il alla ensuite, aucune chronique des royaumes ne saurait le dire.]=],
		},
	},
	bonds = {
		{ id = "malfurion-stormrage", name = "Malfurion Stormrage", note = "son frère jumeau" },
		{ id = "tyrande-whisperwind", name = "Tyrande Whisperwind", note = "l'amour qu'il perdit" },
		{ id = "queen-azshara", name = "Reine Azshara", note = "ennemie d'autrefois" },
		{ id = "arthas-menethil", name = "Arthas Menethil", note = "le vainquit à la Couronne de glace" },
		{ id = "gul-dan", name = "Gul'dan", note = "dont il absorba le crâne" },
	},
})

Translate("frFR", "malfurion-stormrage", {
	title = "Malfurion Stormrage",
	subtitle = "Le premier druide",
	allegiance = "Elfes de la nuit · Cercle cénarien",
	aliases = { "Malfurion" },
	sections = {
		{
			title = "Résumé",
			text = [=[Malfurion Stormrage fut le premier druide {link:night-elves}elfe de la nuit{/link}, l'élève du demi-dieu {link:cenarius}Cenarius{/link} et le frère jumeau d'{link:illidan-stormrage}Illidan Stormrage{/link}. Il mena la lutte contre la {link:burning-legion}Légion ardente{/link} pendant la {link:war-of-the-ancients}guerre des Anciens{/link} et de nouveau pendant la {link:third-war}Troisième Guerre{/link}. Il est l'aimé de {link:tyrande-whisperwind}Tyrande Whisperwind{/link}. Il dort aujourd'hui dans le {link:emerald-dream}Rêve d'émeraude{/link}, et son peuple attend son réveil.]=],
		},
		{
			title = "Importance",
			text = [=[Malfurion sauva le monde deux fois. Dans les temps anciens, il détruisit le {link:well-of-eternity}puits d'Éternité{/link} pour fermer la porte à la Légion. Dix mille ans plus tard, il détruisit {link:archimonde}Archimonde{/link} au pied de l'Arbre-Monde. Les druides de toutes les terres suivent la voie qu'il fut le premier à parcourir.]=],
		},
		{
			title = "La guerre des Anciens",
			text = [=[Malfurion était attiré par le monde vivant tandis que son frère étudiait les arcanes. {link:cenarius}Cenarius{/link} le prit pour élève et lui apprit à façonner les puissances de la nature. Quand la {link:queen-azshara}reine Azshara{/link} et ses Bien-nés firent entrer la Légion dans le monde, Malfurion rejoignit la résistance. Il comprit que la Légion ne pourrait être arrêtée qu'en détruisant le puits d'Éternité lui-même. Son attaque contre le Puits déclencha la {link:great-sundering}Grande Fracture{/link}, qui brisa la terre et engloutit la capitale de la reine. Quand {link:illidan-stormrage}Illidan{/link} créa un nouveau Puits sur le {link:mount-hyjal}mont Hyjal{/link}, Malfurion le fit emprisonner. Avec l'aide des grands dragons, les survivants plantèrent {link:nordrassil}Nordrassil{/link} au-dessus du nouveau Puits. Malfurion et ses druides sombrèrent alors dans un long sommeil dans le {link:emerald-dream}Rêve d'émeraude{/link}.]=],
		},
		{
			title = "La Troisième Guerre",
			text = [=[Quand la Légion revint, {link:tyrande-whisperwind}Tyrande{/link} éveilla les druides. Malfurion les ramena dans le monde et aida à tenir les forêts d'{link:ashenvale}Orneval{/link} contre les démons. Contre sa volonté, Tyrande libéra {link:illidan-stormrage}Illidan{/link}, et il arriva trop tard pour empêcher son frère de prendre la puissance d'un démon. Il bannit Illidan et retourna défendre Hyjal. Là, il se tint aux côtés des orcs de {link:thrall}Thrall{/link} et des hommes de {link:jaina-proudmoore}Jaina Proudmoore{/link}. Quand {link:archimonde}Archimonde{/link} atteignit {link:nordrassil}Nordrassil{/link}, Malfurion sonna le Cor de {link:cenarius}Cenarius{/link}. Les esprits des anciens détruisirent le seigneur démon, et le monde fut sauvé.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il apprit de {link:cenarius}Cenarius{/link} les voies de la nature et devint le premier druide.
• Il détruisit le puits d'Éternité et mit fin à la guerre des Anciens.
• Il emprisonna son frère sous la terre.
• Il mena les druides contre la Légion pendant la {link:third-war}Troisième Guerre{/link}.
• Il détruisit {link:archimonde}Archimonde{/link} lors de la bataille du mont Hyjal.]=],
		},
		{
			title = "Destin",
			text = [=[Après la guerre, Malfurion traqua {link:illidan-stormrage}Illidan{/link} de l'autre côté de la mer, puis le laissa partir. Il retourna dans le {link:emerald-dream}Rêve d'émeraude{/link} et ne s'est pas réveillé depuis. En son absence, l'archidruide {link:fandral-staghelm}Fandral Staghelm{/link} dirige les druides de {link:darnassus}Darnassus{/link}, et les elfes de la nuit ont planté un nouvel Arbre-Monde, {link:teldrassil}Teldrassil{/link}. {link:tyrande-whisperwind}Tyrande{/link} gouverne et attend.]=],
		},
	},
	bonds = {
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "son frère jumeau" },
		{ id = "tyrande-whisperwind", name = "Tyrande Whisperwind", note = "son aimée" },
		{ id = "archimonde", name = "Archimonde", note = "le démon qu'il détruisit" },
		{ id = "queen-azshara", name = "Reine Azshara", note = "la reine qu'il combattit" },
		{ id = "fandral-staghelm", name = "Fandral Staghelm", note = "dirige les druides à sa place" },
	},
})

Translate("frFR", "queen-azshara", {
	title = "Reine Azshara",
	subtitle = "Reine des Bien-nés",
	allegiance = "Bien-nés · Nagas",
	sections = {
		{
			title = "Résumé",
			text = [=[La reine {link:azshara}Azshara{/link} régnait sur l'antique empire des {link:night-elves}elfes de la nuit{/link} à l'apogée de sa gloire. Elle était la plus belle et la plus puissante de son peuple, qui l'adorait. Depuis son palais de Zin-Azshari, au bord du {link:well-of-eternity}puits d'Éternité{/link}, elle guidait les Bien-nés dans l'étude de la {link:arcane-magic}magie des arcanes{/link}. Dans son orgueil, elle ouvrit le monde à la {link:burning-legion}Légion ardente{/link}, et son empire sombra sous la mer.]=],
		},
		{
			title = "Importance",
			text = [=[La trahison d'{link:azshara}Azshara{/link} déclencha la {link:war-of-the-ancients}guerre des Anciens{/link} et s'acheva dans la {link:great-sundering}Grande Fracture{/link}. La forme brisée de {link:kalimdor}Kalimdor{/link} et des {link:eastern-kingdoms}Royaumes de l'est{/link} est son héritage. Les {link:naga}nagas{/link} qui surgissent aujourd'hui des vagues le sont peut-être aussi.]=],
		},
		{
			title = "La reine des Bien-nés",
			text = [=[Le peuple d'{link:azshara}Azshara{/link} donna son nom à des cités et à des montagnes. Les Bien-nés, la caste noble de sa cour, la servaient comme prêtres et sorciers. Sous son règne, ils puisèrent toujours plus profondément dans le puits d'Éternité. Leurs sorts portèrent au-delà du monde et attirèrent le regard de {link:sargeras}Sargeras{/link}. Le seigneur démon murmura à la reine, et elle l'écouta. Elle en vint à croire que le monde devait être purifié de tous les peuples inférieurs, et que Sargeras le ferait.]=],
		},
		{
			title = "La guerre des Anciens",
			text = [=[{link:azshara}Azshara{/link} et ses Bien-nés ouvrirent un portail au sein du Puits, et les démons de la Légion s'y engouffrèrent. Son conseiller Xavius la servit dans cette œuvre. Les elfes de la nuit restés libres se soulevèrent contre leur reine, menés par {link:malfurion-stormrage}Malfurion Stormrage{/link}, {link:tyrande-whisperwind}Tyrande Whisperwind{/link} et le seigneur Kur'talos Ravencrest. Tandis que la guerre faisait rage, les Bien-nés travaillaient à faire entrer {link:sargeras}Sargeras{/link} lui-même dans le monde. Ils ne furent arrêtés que lorsque le Puits fut détruit. Son effondrement déchira la terre, et la mer s'engouffra sur Zin-Azshari.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle régna sur les elfes de la nuit à l'apogée de leur puissance.
• Elle guida les Bien-nés dans l'usage du puits d'Éternité.
• Elle ouvrit à la {link:burning-legion}Légion ardente{/link} le chemin d'{link:azeroth}Azeroth{/link}.
• Elle chercha à faire entrer {link:sargeras}Sargeras{/link} lui-même dans le monde.]=],
		},
		{
			title = "Destin",
			text = [=[Quand le Puits s'effondra, Azshara et ses Bien-nés disparurent sous les vagues. Les légendes des elfes de la nuit disent qu'ils ne moururent pas, mais furent changés, et que les nagas serpentins sont ce qu'ils devinrent. Les nagas sont revenus sur les rivages en ces jours, pillant les côtes de {link:kalimdor}Kalimdor{/link} et d'autres terres. Certains d'entre eux parlent de leur antique reine comme si elle vivait encore. Seules les ruines de son empire subsistent dans la terre qui porte son nom, {link:azshara}Azshara{/link}.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucun registre mortel ne dit si {link:azshara}Azshara{/link} vit encore sous la mer, ni ce qu'elle est devenue.]=],
		},
	},
	bonds = {
		{ id = "malfurion-stormrage", name = "Malfurion Stormrage", note = "mena la rébellion contre elle" },
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "combattit sa cour" },
		{ id = "archimonde", name = "Archimonde", note = "un seigneur de la Légion qu'elle servit" },
		{ id = "tyrande-whisperwind", name = "Tyrande Whisperwind", note = "mena la rébellion contre elle" },
	},
})

Translate("frFR", "deathwing", {
	title = "Aile-de-mort",
	subtitle = "Le Destructeur",
	allegiance = "Vol noir",
	aliases = { "Neltharion" },
	sections = {
		{
			title = "Résumé",
			text = [=[Aile-de-mort fut jadis Neltharion, le Gardien de la terre, Aspect du Vol noir. Il avait pour charge de garder les profondeurs du monde. La folie s'empara de lui, et il trahit les autres vols draconiques pendant la {link:war-of-the-ancients}guerre des Anciens{/link}. Depuis, il complote contre tous les peuples d'{link:azeroth}Azeroth{/link}. Son nom signifie la ruine pour les dragons comme pour les mortels.]=],
		},
		{
			title = "Importance",
			text = [=[La traîtrise d'Aile-de-mort faillit anéantir les vols draconiques. Ses manigances pendant la {link:second-war}Deuxième Guerre{/link} donnèrent ses dragons à la {link:horde}Horde{/link}. Sa couvée noire hante encore le {link:blackrock-mountain}Mont Blackrock{/link} et d'autres lieux sombres du monde.]=],
		},
		{
			title = "Le Gardien de la terre",
			text = [=[Dans les jours anciens, cinq grands dragons furent choisis comme Aspects pour garder le monde. Neltharion reçut la domination de la terre et de ses profondeurs. Quelque chose lui murmura depuis les profondeurs de la pierre, et avec le temps son esprit se pervertit. Pendant la guerre des Anciens, il forgea un grand disque d'or, l'Âme des dragons. Il persuada les autres Aspects d'y verser une part de leur puissance, en leur disant qu'il repousserait la {link:burning-legion}Légion ardente{/link}. Au lieu de cela, il le retourna contre eux. La puissance de l'artefact était si grande que son corps commença à se déchirer, et des plaques de métal furent fixées sur son cuir pour le maintenir entier. Il s'enfuit, et l'Âme des dragons fut perdue.]=],
		},
		{
			title = "La Deuxième Guerre",
			text = [=[Aile-de-mort marche depuis longtemps parmi les mortels sous un déguisement humain, tel un noble circulant dans les cours des rois. Les histoires disent qu'il attisait la discorde partout où il le pouvait. Pendant la {link:second-war}Deuxième Guerre{/link}, l'Âme des dragons tomba entre les mains des {link:dragonmaw-clan}orcs Dragonmaw{/link}. Grâce à elle, ils capturèrent {link:alexstrasza}Alexstrasza{/link}, Aspect des dragons rouges, et la retinrent sous {link:grim-batol}Grim Batol{/link}. Ses petits furent élevés comme montures de guerre pour la {link:horde}Horde{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il trahit les Aspects avec l'Âme des dragons pendant la guerre des Anciens.
• Il circula en secret dans les cours des hommes.
• Il laissa l'Âme des dragons tomber aux mains du {link:dragonmaw-clan}clan Dragonmaw{/link}.
• Il tenta de voler les œufs du Vol rouge à {link:grim-batol}Grim Batol{/link}.]=],
		},
		{
			title = "Destin",
			text = [=[Après la {link:second-war}Deuxième Guerre{/link}, les Dragonmaw retenaient toujours {link:alexstrasza}Alexstrasza{/link} captive à {link:grim-batol}Grim Batol{/link}. Aile-de-mort vint chercher ses œufs, pour rebâtir son propre vol. Une petite bande de héros et de dragons libéra la reine rouge, et l'Âme des dragons fut détruite. Aile-de-mort fut chassé, fou de rage. Où il alla, nul ne le sait. La montagne de Grim Batol, dans {link:wetlands}les Paluns{/link}, est évitée par les nains aujourd'hui encore. Ses enfants et son Vol noir parcourent toujours le monde.]=],
		},
	},
	bonds = {
		{ id = "alexstrasza", name = "Alexstrasza", note = "l'Aspect qu'il aida à asservir" },
		{ id = "orgrim-doomhammer", name = "Orgrim Doomhammer", note = "chef de guerre de la Horde qui usa de son présent" },
		{ id = "queen-azshara", name = "Reine Azshara", note = "alliée de la Légion qu'il prétendait combattre" },
	},
})

Translate("frFR", "kel-thuzad", {
	title = "Kel'Thuzad",
	subtitle = "Fondateur du culte des Damnés",
	allegiance = "Fléau · culte des Damnés (autrefois Kirin Tor)",
	sections = {
		{
			title = "Résumé",
			text = [=[Kel'Thuzad fut jadis un archimage de {link:dalaran}Dalaran{/link} et un membre du conseil dirigeant du {link:kirin-tor}Kirin Tor{/link}. Il se tourna vers l'art interdit de la nécromancie, se voua au {red:lich-king}roi-liche{/red} et fonda le {link:cult-of-the-damned}culte des Damnés{/link}. Il répandit la peste qui détruisit {link:lordaeron}Lordaeron{/link}. Tué par le prince {link:arthas-menethil}Arthas Menethil{/link}, il se releva sous la forme d'une liche. Il commande aujourd'hui le {link:scourge}Fléau{/link} en Lordaeron au nom de son maître.]=],
		},
		{
			title = "Importance",
			text = [=[Sans Kel'Thuzad, la peste de non-mort n'aurait peut-être jamais atteint le peuple de {link:lordaeron}Lordaeron{/link}. Il fut la voix du roi-liche parmi les vivants, et il ouvrit à la {link:burning-legion}Légion ardente{/link} le chemin du retour vers {link:azeroth}Azeroth{/link}.]=],
		},
		{
			title = "L'archimage",
			text = [=[Kel'Thuzad était l'un des plus grands mages de {link:dalaran}Dalaran{/link}, mais il jugeait ses confrères trop timorés dans leurs études. Il se mit à explorer l'art noir de la nécromancie. Quand le conseil l'interdit, il ne s'arrêta pas. Une voix l'appela depuis {red:northrend}Norfendre{/red}. Il y répondit, voyagea jusqu'au nord gelé et se voua au roi-liche. Son maître lui promit la vie éternelle.]=],
		},
		{
			title = "Le culte des Damnés",
			text = [=[Kel'Thuzad revint en {link:lordaeron}Lordaeron{/link} et parla aux pauvres et aux épuisés d'une société nouvelle où tous seraient égaux et où nul ne mourrait. Des milliers rejoignirent son culte des Damnés. Par eux, il contamina le grain des greniers du nord avec une peste qui changeait les vivants en morts-vivants. Quand {link:arthas-menethil}Arthas{/link} vint dans le nord combattre la peste, il trouva Kel'Thuzad à {link:ruins-of-andorhal}Andorhal{/link} et le tua. Pourtant, l'esprit du nécromancien demeura, et il murmura au prince tandis que celui-ci tombait.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il étudia la nécromancie au mépris du {link:kirin-tor}Kirin Tor{/link}.
• Il se voua au roi-liche en Norfendre.
• Il fonda le culte des Damnés.
• Il répandit la peste de non-mort par le grain de {link:lordaeron}Lordaeron{/link}.
• Il invoqua {link:archimonde}Archimonde{/link} dans {link:dalaran}Dalaran{/link}.]=],
		},
		{
			title = "Destin",
			text = [=[Quand {link:arthas-menethil}Arthas{/link} devint serviteur du roi-liche, il porta les restes du nécromancien jusqu'en {link:quel-thalas}Quel'Thalas{/link}. Là, dans les eaux du puits de Soleil, Kel'Thuzad renaquit sous la forme d'une liche. Avec le grimoire de {link:medivh}Medivh{/link}, il invoqua {link:archimonde}Archimonde{/link} dans {link:dalaran}Dalaran{/link}, et le seigneur démon réduisit la cité en ruines. Quand Arthas retourna en Norfendre, Kel'Thuzad resta pour gouverner le {link:scourge}Fléau{/link} en {link:lordaeron}Lordaeron{/link}. Il le fait toujours. La grande nécropole de {red:naxxramas}Naxxramas{/red} flotte au-dessus des {link:eastern-plaguelands}Maleterres{/link}, et ses cultistes tiennent leur école de savoir occulte dans le vieux château de {link:caer-darrow}Caer Darrow{/link}.]=],
		},
	},
	bonds = {
		{ id = "arthas-menethil", name = "Arthas Menethil", note = "son meurtrier, puis son maître" },
		{ id = "ner-zhul", name = "Ner'zhul", note = "le roi-liche auquel il se voua" },
		{ id = "archimonde", name = "Archimonde", note = "le démon qu'il invoqua" },
		{ id = "terenas-menethil", name = "Terenas Menethil", note = "dont les cendres firent place à ses os" },
	},
})

Translate("frFR", "jaina-proudmoore", {
	title = "Jaina Proudmoore",
	subtitle = "Souveraine de Theramore",
	found = [=[Citadelle de Theramore, île de Theramore, dans le marécage d'Âprefange]=],
	hint = [=[Cherchez la dame de Theramore dans la tour de la citadelle de son île.]=],
	allegiance = "Theramore · Alliance · Kirin Tor",
	aliases = { "Jaina", "dame Jaina Proudmoore", "dame Proudmoore" },
	sections = {
		{
			title = "Résumé",
			text = [=[Dame Jaina Proudmoore gouverne {link:theramore-isle}Theramore{/link}, la place forte insulaire de l'{link:alliance}Alliance{/link} sur la côte est de {link:kalimdor}Kalimdor{/link}. Elle est la fille du grand amiral {link:daelin-proudmoore}Daelin Proudmoore{/link} de {link:kul-tiras}Kul Tiras{/link} et une sorcière formée à {link:dalaran}Dalaran{/link} par le {link:kirin-tor}Kirin Tor{/link}. Elle marcha aux côtés du prince {link:arthas-menethil}Arthas Menethil{/link} au temps de la peste, et elle se sépara de lui avant sa chute. Elle mena les survivants du nord de l'autre côté de la mer, et elle conclut avec la {link:horde}Horde{/link} une paix que nul avant elle n'avait crue possible.]=],
		},
		{
			title = "Importance",
			text = [=[Jaina est le pont entre les anciens ennemis. Elle se tint aux côtés de {link:thrall}Thrall{/link} lors de la {link:battle-of-mount-hyjal}bataille du mont Hyjal{/link}, et elle lui reste fidèle. Cette paix lui coûta son père. Elle est fragile, et beaucoup dans les deux camps aimeraient la voir rompue.]=],
		},
		{
			title = "La peste",
			text = [=[Jeune femme, Jaina étudia la magie à {link:dalaran}Dalaran{/link} sous l'archimage Antonidas, et elle montra des dons rares. Quand une étrange peste se répandit dans les terres agricoles du nord de {link:lordaeron}Lordaeron{/link}, elle partit avec le {link:arthas-menethil}prince Arthas{/link} en chercher la source. Ensemble, ils découvrirent le {link:cult-of-the-damned}culte des Damnés{/link} et le grain contaminé. À Stratholme, Arthas ordonna que les habitants de la cité soient tués avant qu'ils ne se relèvent en morts-vivants. Jaina refusa d'y prendre part, et elle le quitta là. L'{link:culling-of-stratholme}Épuration de Stratholme{/link} se fit sans elle.]=],
		},
		{
			title = "Le voyage vers l'ouest",
			text = [=[Un mystérieux prophète pressa les chefs de l'est de faire voile vers l'ouest, par-delà la mer. Jaina l'écouta quand d'autres ne le firent pas, et elle mena les survivants de {link:lordaeron}Lordaeron{/link} jusqu'en {link:kalimdor}Kalimdor{/link}. Là, elle rencontra {link:thrall}Thrall{/link} et ses orcs, les anciens ennemis de son peuple. Le prophète les réunit contre un ennemi plus grand, et au mont Hyjal, humains, orcs et {link:night-elves}elfes de la nuit{/link} combattirent côte à côte jusqu'à la destruction d'{link:archimonde}Archimonde{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle étudia la magie parmi le {link:kirin-tor}Kirin Tor{/link} de {link:dalaran}Dalaran{/link}.
• Elle traqua la peste avec {link:arthas-menethil}Arthas{/link} et refusa l'{link:culling-of-stratholme}Épuration de Stratholme{/link}.
• Elle mena les survivants de {link:lordaeron}Lordaeron{/link} vers l'ouest, jusqu'en {link:kalimdor}Kalimdor{/link}.
• Elle combattit aux côtés de {link:thrall}Thrall{/link} et des elfes de la nuit au mont Hyjal.
• Elle fonda {link:theramore-isle}Theramore{/link} et fit la paix avec la {link:horde}Horde{/link}.]=],
		},
		{
			title = "Theramore",
			text = [=[Après la guerre, Jaina éleva {link:theramore-isle}Theramore{/link} sur une île au large du {link:dustwallow-marsh}marécage d'Âprefange{/link}. Puis son père vint en {link:kalimdor}Kalimdor{/link} avec une grande flotte. {link:daelin-proudmoore}Daelin{/link} refusait toute paix avec les orcs, et il leur fit la guerre. Jaina ne put le persuader d'arrêter. Elle ne voulait pas le laisser détruire la paix, et elle resta à l'écart tandis que la {link:horde}Horde{/link} se défendait. Daelin fut tué dans les combats devant les murs de Theramore. Sa fille le pleure, et les marins qui le suivaient ne lui ont pas pardonné.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Jaina gouverne {link:theramore-isle}Theramore{/link} depuis sa citadelle. La cité est un refuge pour le peuple du nord perdu, et une porte d'entrée de l'{link:alliance}Alliance{/link} en {link:kalimdor}Kalimdor{/link}. Elle maintient la paix avec {link:thrall}Thrall{/link} du mieux qu'elle peut, tandis que les soldats des deux camps s'affrontent dans les terres sauvages.]=],
		},
	},
	chapters = {
		{
			title = "Le diplomate disparu",
			hint = "Suivez la piste du diplomate disparu jusqu'à Theramore.",
			text = [=[La piste d'un émissaire enlevé menait de {link:stormwind-city}Stormwind{/link} à {link:menethil-harbor}Port de Menethil{/link}, et de là, de l'autre côté de la mer, jusqu'au marécage d'{link:dustwallow-marsh}Âprefange{/link}. À son extrémité se tenait le soldat {link:private-hendel}Hendel{/link}, un soldat de {link:theramore-isle}Theramore{/link} qui s'était vendu à la {link:defias-brotherhood}Confrérie défias{/link}. Quand il fut démasqué, il tira sa lame. Jaina et ses gardes vinrent le prendre vivant, car un traître mort ne dit rien. La dame de Theramore remercia discrètement ceux qui avaient fait éclater la vérité. Elle ne pouvait les remercier ouvertement. Ce que Hendel sait du roi disparu de Stormwind est l'affaire de ses interrogateurs.]=],
		},
	},
	mentions = {
		{ text = "The Missing Diplomat" },
		{ text = "The Missing Diplomat" },
	},
	bonds = {
		{ id = "daelin-proudmoore", name = "Daelin Proudmoore", note = "son père" },
		{ id = "arthas-menethil", name = "Arthas Menethil", note = "son compagnon, et son amour perdu" },
		{ id = "thrall", name = "Thrall", note = "son allié dans la paix" },
		{ id = "aegwynn", name = "Aegwynn", note = "l'aurait conseillée" },
		{ id = "tapoke-slim-jahn", name = "Tapoke « Slim » Jahn", note = "aida au complot que ses gardes découvrirent" },
	},
})

Translate("frFR", "khadgar", {
	title = "Khadgar",
	subtitle = "Apprenti du dernier Gardien",
	allegiance = "Kirin Tor · Alliance de Lordaeron",
	sections = {
		{
			title = "Résumé",
			text = [=[Khadgar était un jeune mage de {link:dalaran}Dalaran{/link} envoyé par le {link:kirin-tor}Kirin Tor{/link} servir d'apprenti à {link:medivh}Medivh{/link}, le dernier Gardien de {link:tirisfal-glades}Tirisfal{/link}. Il fut le premier à comprendre que le Gardien lui-même avait amené les orcs sur {link:azeroth}Azeroth{/link}. Il combattit pendant la {link:first-war}Première Guerre{/link} et la {link:second-war}Deuxième Guerre{/link}, et il devint l'un des grands archimages de son temps. Il franchit la {link:dark-portal}Porte des Ténèbres{/link} il y a longtemps, et il n'est pas revenu.]=],
		},
		{
			title = "Importance",
			text = [=[Khadgar fit sortir la vérité de {link:karazhan}Karazhan{/link}. Sans lui, {link:stormwind-city}Stormwind{/link} n'aurait peut-être jamais su qui était son véritable ennemi. Pendant la {link:second-war}Deuxième Guerre{/link}, il se tint aux côtés d'{link:anduin-lothar}Anduin Lothar{/link} comme l'un des chefs de l'{link:alliance}Alliance{/link}, et à la fin il ferma le passage entre les mondes au prix de son propre retour.]=],
		},
		{
			title = "Karazhan",
			text = [=[Les mages de {link:dalaran}Dalaran{/link} souhaitaient depuis longtemps percer les secrets de {link:karazhan}la tour de Medivh{/link}. Ils y envoyèrent Khadgar comme apprenti, et lui ordonnèrent d'observer. Le Gardien l'accueillit et l'instruisit. Khadgar découvrit bientôt que son maître avait de longs silences, d'étranges visions et une noirceur dont il refusait de parler. Avec la demi-orque {link:garona}Garona{/link}, venue à la tour comme émissaire de la {link:horde}Horde{/link}, il découvrit que {link:medivh}Medivh{/link} lui-même avait ouvert la {link:dark-portal}Porte des Ténèbres{/link}. Tous deux portèrent l'avertissement au roi {link:llane-wrynn}Llane Wrynn{/link}. Puis Khadgar gravit Karazhan avec {link:anduin-lothar}Lothar{/link} pour affronter son maître. Medivh fut tué. Dans ce combat, le jeune mage vieillit de nombreuses années en un instant, et il redescendit de la tour avec le visage d'un vieil homme.]=],
		},
		{
			title = "La Deuxième Guerre",
			text = [=[Khadgar partit vers le nord avec {link:anduin-lothar}Lothar{/link} et les exilés de {link:stormwind-city}Stormwind{/link}. En {link:lordaeron}Lordaeron{/link}, il fut l'un des lieutenants du champion, avec le paladin {link:turalyon}Turalyon{/link}. Il combattit la {link:horde}Horde{/link} à travers les royaumes du nord et contribua à sa défaite au {link:blackrock-mountain}Mont Blackrock{/link}. Quand la guerre fut gagnée, l'{link:alliance}Alliance{/link} détruisit la {link:dark-portal}Porte des Ténèbres{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il fut le dernier apprenti de {link:medivh}Medivh{/link} à {link:karazhan}Karazhan{/link}.
• Il découvrit le rôle de Medivh dans la venue des orcs et avertit le {link:llane-wrynn}roi Llane{/link}.
• Il combattit aux côtés d'{link:anduin-lothar}Anduin Lothar{/link} quand Medivh fut tué.
• Il fut lieutenant de l'{link:alliance}Alliance{/link} pendant la {link:second-war}Deuxième Guerre{/link}.
• Il mena l'Alliance au-delà de la {link:dark-portal}Porte des Ténèbres{/link} après la guerre.]=],
		},
		{
			title = "Au-delà de la Porte",
			text = [=[Quelques années après la {link:second-war}Deuxième Guerre{/link}, la Porte s'ouvrit de nouveau. Des orcs la franchirent depuis {red:draenor}Draenor{/red} pour voler des reliques de pouvoir, envoyés par le vieux chaman {link:ner-zhul}Ner'zhul{/link}. L'{link:alliance}Alliance{/link} envoya une armée à leur poursuite dans le monde natal des orcs. Khadgar la mena avec {link:turalyon}Turalyon{/link}. Les sorts de Ner'zhul déchirèrent Draenor. Pour empêcher la ruine de se répandre sur {link:azeroth}Azeroth{/link}, les chefs de l'Alliance choisirent de fermer la Porte depuis l'autre côté. Ils savaient qu'ils ne pourraient pas rentrer. La Porte se tut, et l'expédition fut perdue pour les siens.]=],
		},
		{
			title = "Destin",
			text = [=[Aucune nouvelle de Khadgar n'est parvenue aux royaumes depuis la fermeture de la Porte. Dans les {link:blasted-lands}Terres foudroyées{/link}, les mages du {link:kirin-tor}Kirin Tor{/link} veillent sur la porte en ruine depuis la {link:nethergarde-keep}forteresse de Rempart-du-Néant{/link}, et ils ne l'ont pas oublié.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucune chronique des royaumes ne dit ce qu'il advint de Khadgar et de ses compagnons au-delà de la Porte.]=],
		},
	},
	bonds = {
		{ id = "medivh", name = "Medivh", note = "son maître" },
		{ id = "garona", name = "Garona", note = "son alliée à Karazhan" },
		{ id = "anduin-lothar", name = "Anduin Lothar", note = "son commandant" },
		{ id = "turalyon", name = "Turalyon", note = "son compagnon de deux guerres" },
		{ id = "ner-zhul", name = "Ner'zhul", note = "son ennemi au-delà de la Porte" },
	},
})

Translate("frFR", "turalyon", {
	title = "Turalyon",
	subtitle = "Vainqueur de la Deuxième Guerre",
	allegiance = "Chevaliers de la Main d'argent · Alliance de Lordaeron",
	sections = {
		{
			title = "Résumé",
			text = [=[Turalyon était un jeune prêtre de la {link:holy-light}Lumière sacrée{/link} qui devint l'un des premiers paladins des Chevaliers de la Main d'argent. Il servit comme lieutenant d'{link:anduin-lothar}Anduin Lothar{/link} pendant la {link:second-war}Deuxième Guerre{/link}. Quand Lothar tomba, Turalyon reprit son commandement et gagna la guerre. Il mena ensuite l'{link:alliance}Alliance{/link} au-delà de la {link:dark-portal}Porte des Ténèbres{/link}, et il ne revint pas.]=],
		},
		{
			title = "Importance",
			text = [=[C'est Turalyon qui changea l'heure la plus sombre de l'{link:alliance}Alliance{/link} en victoire. Sa charge au {link:blackrock-mountain}Mont Blackrock{/link} brisa l'ancienne {link:horde}Horde{/link}, et la paix que connurent les royaumes du nord pendant une génération fut son présent.]=],
		},
		{
			title = "La Main d'argent",
			text = [=[Turalyon était prêtre de l'Église en {link:lordaeron}Lordaeron{/link} quand les exilés de {link:stormwind-city}Stormwind{/link} arrivèrent dans le nord. {link:anduin-lothar}Lothar{/link} vit de la force en lui et fit de lui l'un de ses lieutenants, avec le mage {link:khadgar}Khadgar{/link}. Turalyon doutait de lui-même et de sa foi. Pourtant, il fut parmi les premiers chevaliers que l'archevêque {link:alonsus-faol}Alonsus Faol{/link} forma à manier la Lumière au combat, avec {link:uther-the-lightbringer}Uther le Porteur de Lumière{/link}, {link:tirion-fordring}Tirion Fordring{/link} et quelques autres. Il mena les armées de l'{link:alliance}Alliance{/link} contre la {link:horde}Horde{/link} dans le nord, et il apprit à se fier à la puissance qui lui avait été donnée.]=],
		},
		{
			title = "Le Mont Blackrock",
			text = [=[À la fin de la guerre, l'{link:alliance}Alliance{/link} repoussa la {link:horde}Horde{/link} vers le sud jusqu'au {link:blackrock-mountain}Mont Blackrock{/link}. Dans la bataille au pied de la montagne, le chef de guerre {link:orgrim-doomhammer}Orgrim Doomhammer{/link} tua {link:anduin-lothar}Lothar{/link}. Les soldats de l'Alliance vacillèrent. Turalyon reprit l'épée de son commandant et les rallia. Les paladins invoquèrent la Lumière, et la Horde fut brisée. Doomhammer fut fait prisonnier. Turalyon poursuivit les derniers orcs jusqu'à la {link:dark-portal}Porte des Ténèbres{/link}, et l'Alliance détruisit la porte.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il fut parmi les premiers paladins de la Main d'argent.
• Il servit comme lieutenant d'{link:anduin-lothar}Anduin Lothar{/link} pendant la {link:second-war}Deuxième Guerre{/link}.
• Il rallia l'{link:alliance}Alliance{/link} après la mort de Lothar et gagna la bataille du {link:blackrock-mountain}Mont Blackrock{/link}.
• Il repoussa la {link:horde}Horde{/link} jusqu'à la {link:dark-portal}Porte des Ténèbres{/link} et la vit détruite.
• Il mena l'armée de l'Alliance sur {red:draenor}Draenor{/red} avec {link:khadgar}Khadgar{/link}.]=],
		},
		{
			title = "Au-delà de la Porte",
			text = [=[Quelques années plus tard, la Porte s'ouvrit de nouveau, et des orcs la franchirent pour voler des reliques de pouvoir pour le chaman {link:ner-zhul}Ner'zhul{/link}. Turalyon mena l'armée de l'{link:alliance}Alliance{/link} sur Draenor avec {link:khadgar}Khadgar{/link}. Avec eux partirent la forestière Alleria Windrunner, sœur aînée de {link:sylvanas-windrunner}Sylvanas Windrunner{/link}, et d'autres héros de la guerre. L'expédition combattit les orcs à travers leur monde brisé. Quand les sorts de Ner'zhul commencèrent à déchirer Draenor, ses chefs fermèrent la Porte depuis l'autre côté pour que la ruine n'atteigne pas {link:azeroth}Azeroth{/link}. Ils ne purent rentrer.]=],
		},
		{
			title = "Destin",
			text = [=[Turalyon n'a pas été revu dans les royaumes depuis la fermeture de la Porte. Les paladins du nord prononcent encore son nom à côté de celui d'{link:uther-the-lightbringer}Uther{/link}.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucune chronique des royaumes ne rapporte ce qu'il advint de Turalyon au-delà de la Porte.]=],
		},
	},
	bonds = {
		{ id = "anduin-lothar", name = "Anduin Lothar", note = "son commandant" },
		{ id = "khadgar", name = "Khadgar", note = "son compagnon de deux guerres" },
		{ id = "uther-the-lightbringer", name = "Uther le Porteur de Lumière", note = "un frère de la Main d'argent" },
		{ id = "orgrim-doomhammer", name = "Orgrim Doomhammer", note = "le chef de guerre qu'il vainquit" },
		{ id = "alonsus-faol", name = "Alonsus Faol", note = "l'ordonna" },
	},
})

Translate("frFR", "tirion-fordring", {
	title = "Tirion Fordring",
	subtitle = "Le paladin exilé",
	found = [=[Une cabane isolée au bord de la rivière, à la lisière ouest des Maleterres de l'est]=],
	hint = [=[Cherchez l'ermite qui pêche près d'une cabane à la lisière ouest des Maleterres de l'est.]=],
	allegiance = "Aucune (autrefois les Chevaliers de la Main d'argent)",
	aliases = { "Tirion" },
	sections = {
		{
			title = "Résumé",
			text = [=[Tirion Fordring fut jadis le seigneur du Donjon de Mardenholde et l'un des premiers paladins de la Main d'argent. Il fut dépouillé de ses terres et de ses titres pour avoir défendu un {link:orcs}orc{/link}, et chassé en exil. Il vit aujourd'hui seul dans une cabane des {link:eastern-plaguelands}Maleterres de l'est{/link}, un vieil homme dans une terre de morts. Son fils dirige la {link:scarlet-crusade}Croisade écarlate{/link} à {link:hearthglen}Hearthglen{/link}, et croit que son père est mort depuis longtemps.]=],
		},
		{
			title = "Importance",
			text = [=[Tirion est un homme de la Lumière qui garda son honneur quand son ordre et son royaume ne le firent pas. Peu en {link:lordaeron}Lordaeron{/link} se souviennent de lui. Pourtant, les orcs qui connaissent son histoire l'honorent, et le récit de sa chute parle à quiconque a dû choisir entre la loi et ce qui est juste.]=],
		},
		{
			title = "La Main d'argent",
			text = [=[Tirion fut parmi les premiers chevaliers formés par l'archevêque {link:alonsus-faol}Alonsus Faol{/link}, avec {link:uther-the-lightbringer}Uther le Porteur de Lumière{/link} et {link:turalyon}Turalyon{/link}. Il combattit la {link:horde}Horde{/link} pendant la {link:second-war}Deuxième Guerre{/link}. Après la guerre, il gouverna les terres de {link:hearthglen}Hearthglen{/link} depuis le Donjon de Mardenholde avec son épouse, Karandra, et son fils, {link:taelan-fordring}Taelan{/link}.]=],
		},
		{
			title = "Le procès",
			text = [=[Un jour, Tirion tomba sur un vieux guerrier {link:orcs}orc{/link} caché dans les ruines près de ses terres. C'était {link:eitrigg}Eitrigg{/link}. L'orc aurait pu le tuer, et il l'épargna. Tirion vit de l'honneur en lui et le laissa partir. Quand ses propres soldats vinrent tuer l'orc, Tirion le défendit. Pour cela, il fut jugé pour trahison. Il fut dépouillé de ses terres et de ses titres et banni de l'ordre. Son épouse dit à leur fils qu'il était mort, et {link:taelan-fordring}Taelan{/link} fut conduit devant la fausse tombe de son père.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il fut parmi les premiers paladins des Chevaliers de la Main d'argent.
• Il combattit la {link:horde}Horde{/link} pendant la {link:second-war}Deuxième Guerre{/link}.
• Il gouverna le Donjon de Mardenholde et les terres autour de {link:hearthglen}Hearthglen{/link}.
• Il épargna l'{link:orcs}orc{/link} {link:eitrigg}Eitrigg{/link} et le défendit contre ses propres hommes.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Tirion vit seul au bord de la rivière, loin de toute route. Son fils {link:taelan-fordring}Taelan{/link} est devenu paladin et il est aujourd'hui généralissime de la {link:scarlet-crusade}Croisade écarlate{/link} à {link:hearthglen}Hearthglen{/link}, lié à un ordre qui s'est égaré. {link:eitrigg}Eitrigg{/link} sert {link:thrall}Thrall{/link} à {link:orgrimmar}Orgrimmar{/link} et n'a pas oublié l'homme qui le sauva.]=],
		},
	},
	chapters = {
		{
			title = "Rédemption",
			hint = [=[Asseyez-vous avec le vieil homme au bord de la rivière et écoutez son récit.]=],
			text = [=[Tirion demanda seulement à son hôte de s'asseoir et d'écouter. Il raconta sa chute et parla de son fils, qui avait grandi sans lui. Il ne demanda pas que son propre nom soit lavé. Il demanda que {link:taelan-fordring}Taelan{/link} soit sauvé de ce que la Croisade avait fait de lui.]=],
		},
		{
			title = "Souvenirs oubliés",
			hint = [=[Récupérez un jouet dans une fausse tombe au sud des Maleterres.]=],
			text = [=[Quand {link:taelan-fordring}Taelan{/link} avait sept ans, son père lui donna un petit marteau de guerre, réplique du sien. Après le bannissement de Tirion, l'enfant l'enterra sur la fausse tombe de son père, dans le caveau de {link:zaeldarr-the-outcast}Zaeldarr{/link}. Il y était resté depuis, et Tirion demanda qu'on le lui rapporte.]=],
		},
		{
			title = "L'honneur perdu",
			hint = "Récupérez ce que Taelan jeta à terre à Valnord.",
			text = [=[Quand {link:uther-the-lightbringer}Uther{/link} tomba et que la Main d'argent fut détruite, le jeune {link:taelan-fordring}Taelan{/link} continua de se battre aussi longtemps qu'il le put. Au hameau de {link:northdale}Valnord{/link}, il livra un dernier combat, et là il jeta la bannière de l'ordre à terre et lui tourna le dos. Tirion contempla la bannière déchirée et se souvint du jour où il avait prêté son propre serment.]=],
		},
		{
			title = "En rêve",
			hint = "Amenez Taelan à son père.",
			text = [=[{link:taelan-fordring}Taelan{/link} rêvait de son père depuis des années. Se souvenant de ce qu'il avait été, il quitta {link:hearthglen}Hearthglen{/link} pour le retrouver. La Croisade le traqua sur la route, et le grand inquisiteur Isillien le tua sous les yeux de son père. Dans son chagrin, Tirion déclara que l'ordre qu'il avait servi n'était pas mort. Il se proclama généralissime d'une nouvelle Main d'argent, renée de l'ancienne.]=],
		},
	},
	mentions = {
		{ text = "Redemption" },
		{ text = "Of Forgotten Memories" },
		{ text = "Of Lost Honor" },
		{ text = "De l'amour et de la famille" },
		{ text = "In Dreams" },
	},
	bonds = {
		{ id = "eitrigg", name = "Eitrigg", note = "l'orc qu'il épargna" },
		{ id = "uther-the-lightbringer", name = "Uther le Porteur de Lumière", note = "un frère de la Main d'argent" },
		{ id = "alonsus-faol", name = "Alonsus Faol", note = "son maître dans la Lumière" },
		{ id = "turalyon", name = "Turalyon", note = "un frère de la Main d'argent" },
	},
})

Translate("frFR", "garona", {
	title = "Garona",
	subtitle = "La demi-orque",
	allegiance = "Inconnue (autrefois le Conseil des ombres)",
	sections = {
		{
			title = "Résumé",
			text = [=[Garona était une demi-orque de sang mêlé, espionne et émissaire de la {link:horde}Horde{/link} pendant la {link:first-war}Première Guerre{/link}. Le démoniste {link:gul-dan}Gul'dan{/link} l'envoya à la tour de {link:medivh}Medivh{/link}. Là, elle se lia d'amitié avec le jeune mage {link:khadgar}Khadgar{/link}, et elle en vint à servir le roi {link:llane-wrynn}Llane Wrynn{/link} de {link:stormwind-city}Stormwind{/link}. Elle l'assassina aussi.]=],
		},
		{
			title = "Importance",
			text = [=[Garona aida à faire connaître à {link:stormwind-city}Stormwind{/link} la vérité sur la trahison de {link:medivh}Medivh{/link}, et elle porta le coup qui mit fin à son roi. Ces deux actes furent les siens, et aucun ne lui appartint tout à fait.]=],
		},
		{
			title = "Émissaire et espionne",
			text = [=[Garona était méprisée des orcs pour son sang mêlé, et elle apprit tôt à survivre par sa ruse. Le {link:shadow-council}Conseil des ombres{/link} de {link:gul-dan}Gul'dan{/link} se servit d'elle. Elle vint à {link:karazhan}Karazhan{/link} comme émissaire de la {link:horde}Horde{/link} auprès du Gardien. Là, {link:khadgar}Khadgar{/link} et elle découvrirent que {link:medivh}Medivh{/link} lui-même avait amené les orcs sur {link:azeroth}Azeroth{/link}. Elle se tint aux côtés de Khadgar et d'{link:anduin-lothar}Anduin Lothar{/link} quand le Gardien fut tué. Ensuite, elle entra au service de {link:stormwind-city}Stormwind{/link} et devint une conseillère de confiance du roi.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle fut l'émissaire de la {link:horde}Horde{/link} auprès de {link:medivh}Medivh{/link} à {link:karazhan}Karazhan{/link}.
• Elle aida {link:khadgar}Khadgar{/link} à découvrir la trahison de Medivh.
• Elle fut présente à la mort du Gardien.
• Elle tua le {link:llane-wrynn}roi Llane{/link} Wrynn dans son propre donjon.]=],
		},
		{
			title = "Destin",
			text = [=[L'esprit de Garona ne lui appartenait pas. Les démonistes du {link:shadow-council}Conseil des ombres{/link} exerçaient un pouvoir caché sur sa volonté. Quand {link:orgrim-doomhammer}Orgrim Doomhammer{/link} assiégea {link:stormwind-city}Stormwind{/link} pour la dernière fois, elle tua {link:llane-wrynn}Llane{/link} dans sa chambre, et le jeune prince {link:varian-wrynn}Varian Wrynn{/link} la vit. Puis elle s'enfuit. Nul dans les royaumes ne sait où elle alla.]=],
		},
		{
			title = "Non consigné",
			text = [=[Où Garona est allée depuis la chute de {link:stormwind-city}Stormwind{/link}, et si elle vit encore, les chroniques ne le disent pas.]=],
		},
	},
	bonds = {
		{ id = "llane-wrynn", name = "Llane Wrynn", note = "son roi, et sa victime" },
		{ id = "khadgar", name = "Khadgar", note = "son ami à Karazhan" },
		{ id = "medivh", name = "Medivh", note = "le Gardien auprès duquel elle fut émissaire" },
		{ id = "gul-dan", name = "Gul'dan", note = "son maître" },
	},
})

Translate("frFR", "alexstrasza", {
	title = "Alexstrasza",
	subtitle = "Reine des dragons rouges",
	allegiance = "Vol rouge",
	aliases = { "Alexstrasza la Lieuse-de-vie" },
	sections = {
		{
			title = "Résumé",
			text = [=[Alexstrasza est l'Aspect du Vol rouge, la Reine des dragons, gardienne de la vie. Dans les jours anciens, les créateurs du monde lui donnèrent pouvoir sur tous les êtres vivants. Elle veille sur {link:azeroth}Azeroth{/link} depuis avant que les elfes ne bâtissent leurs premières cités. Dans les années de la {link:second-war}Deuxième Guerre{/link}, elle fut prisonnière des orcs, et ses enfants furent changés en armes de guerre.]=],
		},
		{
			title = "Importance",
			text = [=[Aucune race mortelle n'a plus souffert de la trahison d'{link:deathwing}Aile-de-mort{/link} que les dragons rouges. Leur captivité à {link:grim-batol}Grim Batol{/link} donna ses dragons à la {link:horde}Horde{/link}, et elle reste la cause de la haine entre le Vol rouge et les orcs du {link:dragonmaw-clan}clan Dragonmaw{/link}.]=],
		},
		{
			title = "Les Aspects",
			text = [=[Dans les jours anciens, cinq grands dragons furent choisis pour garder le monde. Alexstrasza, la plus grande d'entre eux, fut faite gardienne de toute vie. {link:deathwing}Neltharion{/link}, le Gardien de la terre, était son pair. Pendant la {link:war-of-the-ancients}guerre des Anciens{/link}, il persuada les Aspects de verser une part de leur puissance dans son grand disque d'or, l'Âme des dragons, puis il le retourna contre eux. Les dragons furent dispersés et le Vol rouge souffrit terriblement. Alexstrasza ne l'oublia jamais.]=],
		},
		{
			title = "Grim Batol",
			text = [=[Pendant la {link:second-war}Deuxième Guerre{/link}, l'Âme des dragons tomba entre les mains des {link:dragonmaw-clan}orcs Dragonmaw{/link}. Grâce à sa puissance, ils s'emparèrent d'Alexstrasza et l'enchaînèrent sous la montagne de {link:grim-batol}Grim Batol{/link}, dans {link:wetlands}les Paluns{/link}. Ils prenaient ses œufs à mesure qu'elle les pondait, et ils élevaient ses petits comme montures de guerre. Les dragons rouges volèrent pour la {link:horde}Horde{/link} contre l'{link:alliance}Alliance{/link}, incendiant les forêts de {link:quel-thalas}Quel'Thalas{/link} et les villes du nord.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle fut choisie comme Aspect de la vie dans les jours anciens.
• Elle fut trahie par {link:deathwing}Neltharion{/link} pendant la guerre des Anciens.
• Elle fut retenue captive par les Dragonmaw à {link:grim-batol}Grim Batol{/link}.
• Elle fut libérée, et elle vit l'Âme des dragons détruite.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Longtemps après la guerre, les Dragonmaw retenaient toujours la reine. {link:deathwing}Aile-de-mort{/link} vint à {link:grim-batol}Grim Batol{/link} chercher ses œufs, dans l'intention de prendre ses enfants pour les siens. Une petite bande de héros et de dragons libéra Alexstrasza. L'Âme des dragons fut détruite, et sa puissance lui revint. Les dragons rouges se retournèrent contre leurs geôliers et chassèrent Aile-de-mort. Les Dragonmaw s'accrochent toujours aux {link:wetlands}Paluns{/link}, et les dragons rouges les traquent toujours. Où demeure aujourd'hui la Reine des dragons elle-même, peu de mortels le savent.]=],
		},
		{
			title = "Non consigné",
			text = [=[Les chroniques des royaumes disent peu de chose de l'endroit où la Reine des dragons est allée depuis sa libération.]=],
		},
	},
	bonds = {
		{ id = "deathwing", name = "Aile-de-mort", note = "son pair parmi les Aspects, et son traître" },
		{ id = "queen-azshara", name = "Reine Azshara", note = "dont la guerre vit les Aspects trahis" },
	},
})

Translate("frFR", "cenarius", {
	title = "Cenarius",
	subtitle = "Seigneur de la forêt",
	allegiance = "Les forêts de Kalimdor · Cercle cénarien",
	sections = {
		{
			title = "Résumé",
			text = [=[Cenarius était un demi-dieu de la nature sauvage, le seigneur des forêts de {link:kalimdor}Kalimdor{/link}. Les {link:night-elves}elfes de la nuit{/link} le tenaient pour un enfant de leur déesse lunaire, Elune. Il fut le maître de {link:malfurion-stormrage}Malfurion Stormrage{/link} et le père des arts druidiques parmi les mortels. Il tomba pendant la {link:third-war}Troisième Guerre{/link}, tué par {link:grom-hellscream}Grom Hellscream{/link} dans les bois d'{link:ashenvale}Orneval{/link}.]=],
		},
		{
			title = "Importance",
			text = [=[Chaque druide qui parcourt le monde suit une voie que Cenarius ouvrit. Le {link:cenarion-circle}Cercle cénarien{/link}, qui réunit druides elfes de la nuit et {link:tauren}taurens{/link}, porte son nom. Sa mort fut une blessure pour les forêts de {link:kalimdor}Kalimdor{/link}, et les elfes de la nuit ne l'ont pas pardonnée.]=],
		},
		{
			title = "Le premier druide",
			text = [=[À l'âge qui précéda la {link:war-of-the-ancients}guerre des Anciens{/link}, Cenarius demeurait dans les bosquets du mont Hyjal. Il prit le jeune {link:malfurion-stormrage}Malfurion{/link} pour élève et lui apprit à façonner les puissances de la nature. Quand la {link:burning-legion}Légion ardente{/link} passa par le {link:well-of-eternity}puits d'Éternité{/link}, Cenarius mena les antiques esprits de la forêt au combat aux côtés des elfes de la nuit. Après la {link:great-sundering}Grande Fracture{/link}, les druides de l'ordre de Malfurion reprirent ses enseignements et les conservèrent dix mille ans. Son nom survécut dans le Cor de Cenarius, que Malfurion sonnerait un jour au pied de l'Arbre-Monde.]=],
		},
		{
			title = "Ses enfants",
			text = [=[Cenarius eut de nombreux enfants. On dit que les dryades et les gardiens du bosquet sont les siens. Son fils Zaetar fut le père des premiers centaures, une race qui ne se souvient guère de lui que pour sa colère. Son fils {link:keeper-remulos}Remulos{/link} garde la clairière sacrée de {link:moonglade}Reflet-de-Lune{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il enseigna à {link:malfurion-stormrage}Malfurion{/link} et aux premiers druides les voies de la nature.
• Il mena les esprits de la forêt pendant la guerre des Anciens.
• Il veilla sur les forêts de {link:kalimdor}Kalimdor{/link} pendant dix mille ans.
• Il combattit les orcs venus couper les arbres d'{link:ashenvale}Orneval{/link}.
• Le cor qui porte son nom appela les esprits des anciens contre {link:archimonde}Archimonde{/link} lors de la {link:battle-of-mount-hyjal}bataille du mont Hyjal{/link}.]=],
		},
		{
			title = "Destin",
			text = [=[Pendant la {link:third-war}Troisième Guerre{/link}, les orcs du clan Warsong vinrent en {link:ashenvale}Orneval{/link} pour couper du bois. Les elfes de la nuit les combattirent, et Cenarius vint défendre sa forêt. Les orcs ne purent lui résister. Dans leur désespoir, {link:grom-hellscream}Grom Hellscream{/link} et ses guerriers burent à une source souillée par le sang de {link:mannoroth}Mannoroth{/link}, et l'ancienne rage s'empara d'eux. Dans cette fureur, ils tuèrent le demi-dieu. Cenarius est mort. Ses druides l'honorent encore, et ses enfants gardent toujours ses bosquets.]=],
		},
		{
			title = "Non consigné",
			text = [=[Si quelque puissance de Cenarius survécut à sa mort, les chroniques ne le disent pas.]=],
		},
	},
	bonds = {
		{ id = "malfurion-stormrage", name = "Malfurion Stormrage", note = "son élève" },
		{ id = "grom-hellscream", name = "Grom Hellscream", note = "son meurtrier" },
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "le frère de son élève" },
		{ id = "mannoroth", name = "Mannoroth", note = "dont le sang rendit fous ses meurtriers" },
	},
})

Translate("frFR", "kil-jaeden", {
	title = "Kil'jaeden",
	subtitle = "Le Trompeur",
	allegiance = "Légion ardente",
	aliases = { "Kil'jaeden le Trompeur" },
	sections = {
		{
			title = "Résumé",
			text = [=[Kil'jaeden le Trompeur est l'un des grands seigneurs de la {link:burning-legion}Légion ardente{/link}, soumis à la seule volonté de {link:sargeras}Sargeras{/link}. Il fut jadis un chef des érédars avec {link:archimonde}Archimonde{/link}, et il accepta l'offre du titan noir comme le fit Archimonde. C'est un maître du mensonge. C'est Kil'jaeden qui corrompit les orcs de {red:draenor}Draenor{/red}, et c'est lui qui créa le {red:lich-king}roi-liche{/red}.]=],
		},
		{
			title = "Importance",
			text = [=[Rares sont les calamités de la dernière génération où l'on ne trouve pas la main du Trompeur. Par {link:ner-zhul}Ner'zhul{/link} et {link:gul-dan}Gul'dan{/link}, il fit des orcs une arme. Par le roi-liche, il déchaîna le {link:scourge}Fléau{/link} sur {link:lordaeron}Lordaeron{/link}. Contrairement à {link:archimonde}Archimonde{/link}, il n'a jamais été vaincu.]=],
		},
		{
			title = "Les érédars",
			text = [=[Il y a longtemps, les érédars étaient gouvernés par trois chefs : Kil'jaeden, {link:archimonde}Archimonde{/link} et Velen. {link:sargeras}Sargeras{/link} vint à eux avec des promesses de savoir et de puissance. Kil'jaeden et Archimonde acceptèrent, et eux et leur peuple furent changés en démons. Velen refusa et s'enfuit avec ses fidèles. Kil'jaeden le haït pour cela, et il jura de traquer le peuple de Velen partout où il irait.]=],
		},
		{
			title = "Les orcs",
			text = [=[Le peuple de Velen, les draeneï, arriva enfin sur Draenor, où vivaient les orcs. Kil'jaeden les y trouva. Il se présenta au vieux chaman {link:ner-zhul}Ner'zhul{/link} sous l'apparence d'un esprit des ancêtres, et lui dit que les draeneï complotaient contre son peuple. Quand Ner'zhul commença à douter de lui, le Trompeur se tourna vers son apprenti, {link:gul-dan}Gul'dan{/link}, et lui enseigna les arts de la {link:fel-magic}magie gangrenée{/link}. Par Gul'dan, il donna aux orcs le sang de {link:mannoroth}Mannoroth{/link}, les lia à la Légion et les lança contre les draeneï.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il accepta l'offre de {link:sargeras}Sargeras{/link} et devint un seigneur de la Légion.
• Il trompa {link:ner-zhul}Ner'zhul{/link} et dressa les orcs contre les draeneï.
• Il enseigna à {link:gul-dan}Gul'dan{/link} les arts de la magie gangrenée.
• Il fit de Ner'zhul le roi-liche.
• Il envoya le roi-liche préparer {link:azeroth}Azeroth{/link} pour la Légion.]=],
		},
		{
			title = "Le roi-liche",
			text = [=[Quand {link:ner-zhul}Ner'zhul{/link} fuit la ruine de Draenor, Kil'jaeden l'attendait. Il arracha le corps du chaman et lia son esprit à une armure et à un heaume. Il le scella dans la glace et le précipita sur {red:northrend}Norfendre{/red}, lui ordonnant de répandre une peste qui affaiblirait le monde avant l'arrivée de la Légion. Le roi-liche obéit. Quand {link:archimonde}Archimonde{/link} tomba au {link:mount-hyjal}mont Hyjal{/link}, le Trompeur apprit que son serviteur avait commencé à se défaire de ses chaînes.]=],
		},
		{
			title = "Destin",
			text = [=[Kil'jaeden n'a jamais posé le pied sur {link:azeroth}Azeroth{/link}. Après la {link:third-war}Troisième Guerre{/link}, il chercha à faire détruire le roi-liche par d'autres. Le roi-liche perdure, et le Trompeur observe toujours depuis au-delà du monde.]=],
		},
		{
			title = "Non consigné",
			text = [=[Les chroniques ne disent pas où demeure Kil'jaeden, ni ce qu'il projette aujourd'hui.]=],
		},
	},
	bonds = {
		{ id = "archimonde", name = "Archimonde", note = "son pair parmi les seigneurs de la Légion" },
		{ id = "sargeras", name = "Sargeras", note = "son maître" },
		{ id = "ner-zhul", name = "Ner'zhul", note = "le chaman qu'il trompa et fit roi-liche" },
		{ id = "gul-dan", name = "Gul'dan", note = "son serviteur parmi les orcs" },
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "qu'il envoya contre le roi-liche" },
	},
})

Translate("frFR", "sargeras", {
	title = "Sargeras",
	subtitle = "Seigneur de la Légion ardente",
	allegiance = "Légion ardente",
	aliases = { "Le titan noir" },
	sections = {
		{
			title = "Résumé",
			text = [=[Sargeras est le maître de la {link:burning-legion}Légion ardente{/link}, un titan déchu qui cherche à défaire toute la création. Il fut jadis le plus grand champion des titans, les créateurs de mondes, et il combattit les démons du Néant distordu pendant des âges innombrables. Avec le temps, il désespéra de son œuvre. Il libéra les démons qu'il avait emprisonnés, les rassembla en une armée et la tourna contre tous les mondes que les titans avaient façonnés.]=],
		},
		{
			title = "Importance",
			text = [=[Chaque guerre que la Légion a menée sur {link:azeroth}Azeroth{/link} l'a été au nom de Sargeras. Il atteignit le monde trois fois : par la {link:queen-azshara}reine Azshara{/link}, par {link:aegwynn}Aegwynn{/link} et son fils {link:medivh}Medivh{/link}, et par les orcs qu'il lia à sa volonté. Son ombre se tient derrière la {link:war-of-the-ancients}guerre des Anciens{/link}, la {link:first-war}Première Guerre{/link} et la {link:third-war}Troisième Guerre{/link}.]=],
		},
		{
			title = "Le titan déchu",
			text = [=[Les histoires disent que Sargeras chassa les démons à travers les Grandes Ténèbres plus longtemps qu'aucun mortel ne saurait le compter. Ce qu'il y vit changea son cœur. Il en vint à croire que la création elle-même était viciée et ne pouvait être réparée. Il libéra les démons qu'il avait capturés, et il corrompit les érédars par {link:archimonde}Archimonde{/link} et {link:kil-jaeden}Kil'jaeden{/link}, et ainsi naquit la Légion.]=],
		},
		{
			title = "Azeroth",
			text = [=[Il y a dix mille ans, la reine {link:azshara}Azshara{/link} et ses Bien-nés attirèrent son regard par la puissance du {link:well-of-eternity}puits d'Éternité{/link}. Sargeras envoya sa Légion par leur portail, et il chercha à entrer lui-même dans le monde. Le Puits fut détruit avant qu'il ne le puisse. Des âges plus tard, il apparut devant la Gardienne {link:aegwynn}Aegwynn{/link} dans une grande tempête, en {red:northrend}Norfendre{/red}. Elle tua son avatar et scella son corps dans une tombe sous la mer. Son esprit se cacha en elle et passa dans son fils à naître. Par {link:medivh}Medivh{/link}, le titan noir ouvrit la {link:dark-portal}Porte des Ténèbres{/link} et amena les orcs sur {link:azeroth}Azeroth{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il fut jadis le champion des titans.
• Il libéra les démons qu'il avait emprisonnés et fonda la {link:burning-legion}Légion ardente{/link}.
• Il corrompit les érédars par {link:archimonde}Archimonde{/link} et {link:kil-jaeden}Kil'jaeden{/link}.
• Il murmura à {link:azshara}Azshara{/link} et faillit entrer dans le monde.
• Il se cacha en {link:aegwynn}Aegwynn{/link} et en {link:medivh}Medivh{/link}, et ouvrit par lui la {link:dark-portal}Porte des Ténèbres{/link}.]=],
		},
		{
			title = "Destin",
			text = [=[Sargeras n'a jamais marché sur {link:azeroth}Azeroth{/link} sous sa vraie forme. Son avatar gît dans sa tombe sous la mer, que le démoniste {link:gul-dan}Gul'dan{/link} fit surgir et où il entra pour y trouver la mort. Quand {link:medivh}Medivh{/link} fut tué, l'emprise du titan noir sur le monde fut brisée. Pourtant, la Légion qu'il mène demeure, et ses seigneurs n'ont pas renoncé à leur soif de ce monde.]=],
		},
		{
			title = "Non consigné",
			text = [=[Ce qu'il advint de l'esprit de Sargeras à la mort de {link:medivh}Medivh{/link}, les chroniques des royaumes ne sauraient le dire.]=],
		},
	},
	bonds = {
		{ id = "archimonde", name = "Archimonde", note = "son lieutenant" },
		{ id = "kil-jaeden", name = "Kil'jaeden", note = "son lieutenant" },
		{ id = "aegwynn", name = "Aegwynn", note = "tua son avatar" },
		{ id = "medivh", name = "Medivh", note = "son réceptacle" },
		{ id = "queen-azshara", name = "Reine Azshara", note = "sa servante" },
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "reçut son présent" },
	},
})

Translate("frFR", "mannoroth", {
	title = "Mannoroth",
	subtitle = "Le Destructeur",
	allegiance = "Légion ardente",
	aliases = { "Mannoroth le Destructeur" },
	sections = {
		{
			title = "Résumé",
			text = [=[Mannoroth le Destructeur était un seigneur des abîmes de la {link:burning-legion}Légion ardente{/link}, un démon colossal de cornes et de défenses. Il mena les armées de la Légion pendant la {link:war-of-the-ancients}guerre des Anciens{/link}. Plus tard, son sang lia les orcs de {red:draenor}Draenor{/red} à la Légion. Il fut tué en {link:ashenvale}Orneval{/link} par {link:grom-hellscream}Grom Hellscream{/link}, le premier {link:orcs}orc{/link} à l'avoir bu.]=],
		},
		{
			title = "Importance",
			text = [=[La malédiction des orcs était le sang de Mannoroth. Il leur donna force et fureur, et il fit d'eux des esclaves. Sa mort les libéra, et la {link:horde}Horde{/link} de {link:thrall}Thrall{/link} naquit libre grâce à elle.]=],
		},
		{
			title = "Le sang",
			text = [=[Pendant la guerre des Anciens, Mannoroth commandait les démons qui se déversaient par le {link:well-of-eternity}puits d'Éternité{/link}. Quand la Légion se tourna vers Draenor, le démoniste {link:gul-dan}Gul'dan{/link} rassembla les chefs des orcs et leur offrit un calice du sang du seigneur des abîmes. Grom but le premier, et les autres suivirent. Leur peuple devint une {link:horde}Horde{/link} de rage liée à la volonté de la Légion. Longtemps après, Mannoroth vint en {link:ashenvale}Orneval{/link} pendant la {link:third-war}Troisième Guerre{/link}. Quand Grom et ses Warsong désespérèrent de vaincre les défenseurs de la forêt, ils burent à une source que Mannoroth avait souillée de son sang. Dans la fureur qui suivit, ils tuèrent {link:cenarius}Cenarius{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il mena les armées de la Légion pendant la guerre des Anciens.
• Son sang lia les orcs de Draenor à la Légion.
• Il souilla une source en {link:ashenvale}Orneval{/link} et asservit les Warsong une seconde fois.]=],
		},
		{
			title = "Destin",
			text = [=[{link:thrall}Thrall{/link} et Grom allèrent ensemble affronter le seigneur des abîmes dans un canyon d'{link:ashenvale}Orneval{/link}. Mannoroth abattit Thrall. Grom chargea seul et planta sa hache dans la poitrine du démon. Mannoroth mourut, et la malédiction des orcs fut brisée. Grom mourut de ses blessures. Le canyon porte toujours le nom de {link:demon-fall-canyon}Canyon de la Malechute{/link}.]=],
		},
	},
	bonds = {
		{ id = "grom-hellscream", name = "Grom Hellscream", note = "le premier à boire son sang, et son meurtrier" },
		{ id = "gul-dan", name = "Gul'dan", note = "donna son sang aux orcs" },
		{ id = "archimonde", name = "Archimonde", note = "son pair parmi les seigneurs de la Légion" },
		{ id = "cenarius", name = "Cenarius", note = "tué par ceux que son sang rendit fous" },
		{ id = "thrall", name = "Thrall", note = "le combattit avec Grom" },
	},
})
